INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('question.1.prompt', 'es-MX', 'Recibes tu mesada del mes. Después de cubrir gastos fijos, te sobran $2,000 MXN.', 'question'),
  ('question.1.opt.A.text', 'es-MX', 'Lo meto a algo que pueda dar buen rendimiento aunque sea arriesgado', 'question'),
  ('question.1.opt.B.text', 'es-MX', 'Investigo en internet opciones como Cetesdirecto o fondos antes de decidir', 'question'),
  ('question.1.opt.C.text', 'es-MX', 'Lo guardo en mi cuenta y no lo toco, prefiero tenerlo seguro', 'question'),
  ('question.1.opt.D.text', 'es-MX', 'Le pregunto a alguien que sepa de dinero qué me conviene', 'question'),
  ('question.2.prompt', 'es-MX', 'Tu mejor amigo te propone ser socio en un negocio. Necesitas poner $5,000 MXN. Varios del grupo ya dijeron que sí.', 'question'),
  ('question.2.opt.A.text', 'es-MX', 'Si varios ya entraron y confío en mi amigo, le entro también', 'question'),
  ('question.2.opt.B.text', 'es-MX', 'Le digo que no, prefiero no arriesgar mi dinero en algo incierto', 'question'),
  ('question.2.opt.C.text', 'es-MX', 'Le pido el plan de negocio, números, y decido con base en eso', 'question'),
  ('question.2.opt.D.text', 'es-MX', 'Me emociona la idea, le entro de una y quiero participar activamente', 'question'),
  ('question.3.prompt', 'es-MX', 'En tu grupo de amigos todos hablan de una cripto que subió 40% en una semana. Varios ya compraron y te presionan para que entres.', 'question'),
  ('question.3.opt.A.text', 'es-MX', 'Busco información por mi cuenta antes de meter un peso', 'question'),
  ('question.3.opt.B.text', 'es-MX', 'No me importa lo que digan, yo no le entro a cosas que no entiendo bien', 'question'),
  ('question.3.opt.C.text', 'es-MX', 'Si tanta gente está ganando, algo de cierto debe haber, meto una cantidad moderada', 'question'),
  ('question.3.opt.D.text', 'es-MX', 'Le meto con todo, este tipo de oportunidades no se presentan dos veces', 'question'),
  ('question.4.prompt', 'es-MX', 'Es Hot Sale y ves una laptop con 35% de descuento. No la necesitas urgentemente, pero la oferta se acaba en 24 horas.', 'question'),
  ('question.4.opt.A.text', 'es-MX', 'La compro, estas oportunidades no se repiten', 'question'),
  ('question.4.opt.B.text', 'es-MX', 'Comparo specs, reviews, precios en otras tiendas y si conviene la compro', 'question'),
  ('question.4.opt.C.text', 'es-MX', 'No la compro, prefiero guardar ese dinero por si surge algo que sí necesite', 'question'),
  ('question.4.opt.D.text', 'es-MX', 'Le pregunto a alguien que sepa de tecnología si realmente vale la pena', 'question'),
  ('question.5.prompt', 'es-MX', 'Quieres irte de intercambio. Necesitas juntar $80,000 MXN en 10 meses. Hoy tienes $0 ahorrados.', 'question'),
  ('question.5.opt.A.text', 'es-MX', 'Me armo un plan detallado: cuánto ahorrar al mes, en qué instrumento, con fechas', 'question'),
  ('question.5.opt.B.text', 'es-MX', 'Le pido ayuda a mis papás o busco una beca, solo no creo poder', 'question'),
  ('question.5.opt.C.text', 'es-MX', 'Siento que es imposible, mejor busco opciones más baratas', 'question'),
  ('question.5.opt.D.text', 'es-MX', 'Busco generar dinero extra de donde sea — freelance, venta de cosas', 'question'),
  ('question.6.prompt', 'es-MX', 'El banco te ofrece tu primera tarjeta de crédito con un límite de $15,000 MXN.', 'question'),
  ('question.6.opt.A.text', 'es-MX', 'La acepto de volada, tener crédito me abre puertas', 'question'),
  ('question.6.opt.B.text', 'es-MX', 'Investigo la tasa, CAT, anualidad y comparo con otras opciones', 'question'),
  ('question.6.opt.C.text', 'es-MX', 'No la quiero, las tarjetas de crédito te endeudan', 'question'),
  ('question.6.opt.D.text', 'es-MX', 'Le pregunto a alguien de mi familia si es buena idea', 'question'),
  ('question.7.prompt', 'es-MX', 'Ves un anuncio en Instagram de un curso de trading con testimonios de gente que "ya vive de esto". Cuesta $3,000 MXN.', 'question'),
  ('question.7.opt.A.text', 'es-MX', 'Si tanta gente lo recomienda, algo bueno debe tener, me inscribo', 'question'),
  ('question.7.opt.B.text', 'es-MX', 'Busco reseñas independientes, reviso el temario y al instructor antes de pagar', 'question'),
  ('question.7.opt.C.text', 'es-MX', 'Me llama la atención pero $3,000 es mucho, mejor no arriesgo', 'question'),
  ('question.7.opt.D.text', 'es-MX', 'Me inscribo ya, si no funciona al menos aprendí algo', 'question'),
  ('question.8.prompt', 'es-MX', 'Recibes tu primer aguinaldo de unas prácticas profesionales: $8,000 MXN. Es dinero que no esperabas.', 'question'),
  ('question.8.opt.A.text', 'es-MX', 'Lo meto todo a algo agresivo — acciones, cripto — total es dinero extra', 'question'),
  ('question.8.opt.B.text', 'es-MX', 'Lo dejo en mi cuenta de ahorro, así sé que está seguro', 'question'),
  ('question.8.opt.C.text', 'es-MX', 'Pregunto en casa o a un profe de finanzas qué sería lo más inteligente', 'question'),
  ('question.8.opt.D.text', 'es-MX', 'Comparo rendimientos de Cetesdirecto, SOFIPOS y fondos', 'question'),
  ('question.9.prompt', 'es-MX', 'Estás por graduarte. Tienes una oferta de trabajo estable con buen sueldo, pero también una idea de negocio que te apasiona.', 'question'),
  ('question.9.opt.A.text', 'es-MX', 'Analizo ambas opciones a fondo: proyecciones, costos, mercado, y decido con datos', 'question'),
  ('question.9.opt.B.text', 'es-MX', 'Le entro al negocio, la vida es una y no quiero arrepentirme de no intentarlo', 'question'),
  ('question.9.opt.C.text', 'es-MX', 'Tomo el empleo seguro, necesito estabilidad', 'question'),
  ('question.9.opt.D.text', 'es-MX', 'Hablo con gente que admiro profesionalmente y sigo el consejo que más se repita', 'question'),
  ('question.10.prompt', 'es-MX', 'Un compañero de clase te muestra una app donde inviertes desde $100 MXN. Te enseña que lleva 15% de rendimiento en 3 meses.', 'question'),
  ('question.10.opt.A.text', 'es-MX', 'Meto un poco a ver qué pasa, total es poco dinero', 'question'),
  ('question.10.opt.B.text', 'es-MX', 'Descargo la app, reviso quién la regula, leo los términos, y luego decido', 'question'),
  ('question.10.opt.C.text', 'es-MX', 'Suena bien pero mejor espero, no me gusta meter dinero en cosas nuevas', 'question'),
  ('question.10.opt.D.text', 'es-MX', 'Si a mi compañero le está funcionando, le entro con lo mismo que él', 'question'),
  ('question.11.prompt', 'es-MX', 'Recibes una herencia inesperada de $200,000 MXN. No tienes deudas.', 'question'),
  ('question.11.opt.A.text', 'es-MX', 'Lo divido en diferentes instrumentos de mayor riesgo para hacer crecer el capital', 'question'),
  ('question.11.opt.B.text', 'es-MX', 'Construyo un portafolio diversificado basado en mi horizonte de inversión y perfil', 'question'),
  ('question.11.opt.C.text', 'es-MX', 'Lo meto a una cuenta de ahorro de alta seguridad, no quiero arriesgar nada', 'question'),
  ('question.11.opt.D.text', 'es-MX', 'Le pido consejo a mi asesor bancario o a alguien de confianza', 'question'),
  ('question.12.prompt', 'es-MX', 'El mercado de valores cayó 30% en 3 meses. Tus amigos dicen que es hora de comprar más.', 'question'),
  ('question.12.opt.A.text', 'es-MX', 'Si todos los que conozco están comprando, quizás tienen razón', 'question'),
  ('question.12.opt.B.text', 'es-MX', 'Analizo si la valuación actual representa una oportunidad real basado en fundamentos', 'question'),
  ('question.12.opt.C.text', 'es-MX', 'Este nivel de incertidumbre me paraliza, prefiero esperar a que se estabilice', 'question'),
  ('question.12.opt.D.text', 'es-MX', 'Compro agresivamente, las caídas son oportunidades y hay que actuar rápido', 'question'),
  ('question.13.prompt', 'es-MX', 'Debes elegir entre dos fondos de inversión. Fondo A: rendimiento promedio 8%, bajo riesgo. Fondo B: rendimiento promedio 15%, alto riesgo.', 'question'),
  ('question.13.opt.A.text', 'es-MX', 'El Fondo B sin dudarlo, quiero maximizar mi rendimiento', 'question'),
  ('question.13.opt.B.text', 'es-MX', 'Analizo la desviación estándar, el Sharpe ratio y el horizonte de cada opción', 'question'),
  ('question.13.opt.C.text', 'es-MX', 'El Fondo A definitivamente, no quiero perder lo que tengo', 'question'),
  ('question.13.opt.D.text', 'es-MX', 'Le pregunto a mi banco o a alguien de confianza cuál recomienda', 'question'),
  ('question.14.prompt', 'es-MX', 'Tienes una inversión en acciones que ha bajado 40% desde que la compraste.', 'question'),
  ('question.14.opt.A.text', 'es-MX', 'La mantengo y compro más, estoy seguro de que se va a recuperar', 'question'),
  ('question.14.opt.B.text', 'es-MX', 'Evalúo en frío si los fundamentos cambiaron y decido sin importar mi precio de entrada', 'question'),
  ('question.14.opt.C.text', 'es-MX', 'La mantengo pero no compro más, no soporto hacer realidad la pérdida vendiéndola', 'question'),
  ('question.14.opt.D.text', 'es-MX', 'Le pregunto a un broker o analista qué hacer con esta posición', 'question'),
  ('question.15.prompt', 'es-MX', 'Ves que una acción que te gusta está cara según su P/E ratio histórico, pero todos los analistas dicen que va a subir más.', 'question'),
  ('question.15.opt.A.text', 'es-MX', 'Si todos los analistas están optimistas, compro sin esperar', 'question'),
  ('question.15.opt.B.text', 'es-MX', 'Construyo mi propio modelo de valuación independiente antes de decidir', 'question'),
  ('question.15.opt.C.text', 'es-MX', 'Si está cara según los fundamentos, mejor no entro', 'question'),
  ('question.15.opt.D.text', 'es-MX', 'Compro ahora, el momentum puede durar más tiempo del esperado', 'question'),
  ('question.16.prompt', 'es-MX', 'Tienes que decidir cuánto de tu portafolio poner en activos internacionales vs. México.', 'question'),
  ('question.16.opt.A.text', 'es-MX', 'La mayoría en México, conozco mejor el mercado local', 'question'),
  ('question.16.opt.B.text', 'es-MX', 'Analizo correlaciones, diversificación y expectativas macroeconómicas de cada región', 'question'),
  ('question.16.opt.C.text', 'es-MX', '50% internacional, hay que seguir la tendencia global que todos siguen', 'question'),
  ('question.16.opt.D.text', 'es-MX', 'Mayoría internacional, quiero exposición agresiva a mercados de alto crecimiento', 'question'),
  ('question.17.prompt', 'es-MX', 'Tu mejor decisión de inversión te generó 80% de rendimiento. ¿A qué atribuyes ese resultado?', 'question'),
  ('question.17.opt.A.text', 'es-MX', 'Principalmente a mi análisis y timing — identifiqué bien la oportunidad', 'question'),
  ('question.17.opt.B.text', 'es-MX', 'A mi proceso de investigación, aunque el mercado también ayudó', 'question'),
  ('question.17.opt.C.text', 'es-MX', 'Tuve suerte, el mercado cooperó más de lo esperado', 'question'),
  ('question.17.opt.D.text', 'es-MX', 'Seguí el consejo de alguien que sabía más que yo', 'question'),
  ('question.18.prompt', 'es-MX', 'Tu peor decisión de inversión te hizo perder 50% de tu capital. ¿Qué pasó?', 'question'),
  ('question.18.opt.A.text', 'es-MX', 'El mercado se comportó de manera imposible de predecir — fue mala suerte', 'question'),
  ('question.18.opt.B.text', 'es-MX', 'Cometí un error en mi análisis que debo identificar y corregir', 'question'),
  ('question.18.opt.C.text', 'es-MX', 'Me dejé llevar por el pánico en el peor momento', 'question'),
  ('question.18.opt.D.text', 'es-MX', 'Seguí el consejo equivocado de alguien en quien confié', 'question'),
  ('question.19.prompt', 'es-MX', 'Estás construyendo tu plan de retiro. Tienes 30 años por delante.', 'question'),
  ('question.19.opt.A.text', 'es-MX', 'Portafolio 80% renta variable, 20% fija — hay tiempo para recuperar pérdidas', 'question'),
  ('question.19.opt.B.text', 'es-MX', 'Portafolio optimizado basado en curva de riesgo decreciente con la edad', 'question'),
  ('question.19.opt.C.text', 'es-MX', 'Portafolio conservador desde el inicio, no quiero sorpresas', 'question'),
  ('question.19.opt.D.text', 'es-MX', 'Copio la estrategia de algún fondo de pensiones reconocido', 'question'),
  ('question.20.prompt', 'es-MX', 'Simulador de inversión en clase: te dan $100,000 virtuales para un mes. ¿Tu estrategia?', 'question'),
  ('question.20.opt.A.text', 'es-MX', 'Diseño un portafolio diversificado con fundamentals, como si fuera dinero real', 'question'),
  ('question.20.opt.B.text', 'es-MX', 'Le meto la mayor parte a las acciones más volátiles, es simulado y quiero ganar', 'question'),
  ('question.20.opt.C.text', 'es-MX', 'Copio la estrategia de algún fondo reconocido o de lo que el profesor sugirió', 'question'),
  ('question.20.opt.D.text', 'es-MX', 'Pongo casi todo en instrumentos seguros como Cetes, no quiero ver números rojos', 'question')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.contabilidad-mental.name', 'es-MX', 'Contabilidad Mental', 'sesgo'),
  ('sesgo.contabilidad-mental.definition', 'es-MX', 'Tratamos sumas de dinero de manera diferente dependiendo de su origen o uso previsto, ignorando que el dinero es fungible.', 'sesgo'),
  ('sesgo.contabilidad-mental.description', 'es-MX', 'La Contabilidad Mental es un sesgo cognitivo descrito por Richard Thaler (Premio Nobel) en el que creamos "cuentas mentales" separadas para el dinero según su fuente o destino previsto. Esto nos lleva a tomar decisiones irracionales porque ignoramos el principio de fungibilidad: un peso es un peso, sin importar de dónde venga.', 'sesgo'),
  ('sesgo.contabilidad-mental.mechanism', 'es-MX', 'Nuestro Sistema 1 (Kahneman) segrega el dinero en compartimentos psicológicos: el dinero del trabajo es "sagrado", el dinero de la lotería es "para gastar", el dinero del bono es "extra". Esta segmentación viola la lógica económica básica.', 'sesgo'),
  ('sesgo.contabilidad-mental.trapQuestion', 'es-MX', 'Imagina dos situaciones: (A) Vas al cine, pierdes un billete de $200 en la calle. ¿Compras la entrada? / (B) Vas al cine, ya compraste la entrada por $200 y la perdiste. ¿Compras otra? — La mayoría dice Sí a A y No a B. Pero la pérdida económica es idéntica en ambos casos.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.0.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.contabilidad-mental.example.0.text', 'es-MX', 'Un inversor pierde $5,000 en cripto (cuenta de "aventuras") pero guarda intocable su fondo de emergencia. Económicamente son el mismo dinero, pero los trata diferente.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.1.label', 'es-MX', 'Vida personal', 'sesgo'),
  ('sesgo.contabilidad-mental.example.1.text', 'es-MX', 'Gastas sin culpa el dinero de un reembolso de impuestos en algo lujoso, aunque si lo pusieras en tu cuenta normal nunca lo gastarías así.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.2.label', 'es-MX', 'Empresa', 'sesgo'),
  ('sesgo.contabilidad-mental.example.2.text', 'es-MX', 'Una empresa asigna presupuesto por departamento y no lo transfiere aunque otro área lo necesite más urgentemente.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.0', 'es-MX', 'Visualiza todo tu dinero como un único fondo — antes de gastar pregúntate: ¿lo gastaría si viniera de mi nómina?', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.1', 'es-MX', 'Consolida mentalmente tus cuentas: evalúa el portafolio total, no cada inversión en aislado.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.2', 'es-MX', 'Regla del "dinero extra": cualquier ingreso inesperado sigue las mismas reglas que tu ingreso normal.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.3', 'es-MX', 'Lleva un registro unificado de ingresos y gastos sin categorías emocionales.', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.situation', 'es-MX', 'Vas al cine. La entrada cuesta $200. Al llegar, te das cuenta de que perdiste un billete de $200 en la calle. ¿Compras la entrada de todos modos?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.0.text', 'es-MX', 'Sí, son cosas separadas — perder el billete no tiene que ver con el cine', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.0.reveal', 'es-MX', 'Racional: correcto, el dinero es fungible', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.1.text', 'es-MX', 'No, ya perdí $200, no puedo gastar $200 más', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.1.reveal', 'es-MX', 'Sesgo: tratas las pérdidas como vinculadas cuando no lo están', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.situation', 'es-MX', 'Recibes un reembolso de impuestos de $3,000. ¿Cómo lo tratas?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.0.text', 'es-MX', 'Como dinero "extra" — me doy un gusto que no me daría con mi sueldo', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.0.reveal', 'es-MX', 'Sesgo: el origen del dinero no cambia su valor', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.1.text', 'es-MX', 'Igual que cualquier otro ingreso — va a donde más lo necesito', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.1.reveal', 'es-MX', 'Racional: correcto, la fungibilidad aplica independiente del origen', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.situation', 'es-MX', 'Tu portafolio tiene: Cetes +5% y una acción -30%. El Cetes venció hoy. ¿Qué haces con esos fondos?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.0.text', 'es-MX', 'Los reinvierto en Cetes — no quiero mezclarlos con la acción que perdió', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.0.reveal', 'es-MX', 'Sesgo: tratas cada inversión como cuenta separada en lugar del portafolio total', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.1.text', 'es-MX', 'Evalúo qué tiene mejor expectativa de retorno ajustado al riesgo hoy', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.1.reveal', 'es-MX', 'Racional: correcto, el portafolio se optimiza en conjunto', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.question', 'es-MX', '¿Por qué la contabilidad mental es un sesgo y no un sistema racional?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.0', 'es-MX', 'Porque trata el dinero de forma diferente según su origen, cuando en realidad $1 siempre vale $1', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.1', 'es-MX', 'Porque hace que gastemos menos de lo que deberíamos', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.2', 'es-MX', 'Porque solo afecta a personas con poco conocimiento financiero', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.question', 'es-MX', 'Ganas $500 en el casino y los gastas en ropa que normalmente no comprarías. ¿Qué sesgo explica esto?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.0', 'es-MX', 'Contabilidad mental: creaste una cuenta de dinero ganado que sientes libre de gastar', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.1', 'es-MX', 'Exceso de confianza: crees que seguirás ganando', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.2', 'es-MX', 'Efecto manada: todos gastan cuando ganan en el casino', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.question', 'es-MX', '¿Cuál es la implicación financiera más peligrosa de la contabilidad mental?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.0', 'es-MX', 'Que podemos tener deudas con intereses altos y ahorros simultáneamente sin ver la contradicción', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.1', 'es-MX', 'Que nos hace ahorrar demasiado en cuentas separadas', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.2', 'es-MX', 'Que nos impide invertir en más de un instrumento a la vez', 'sesgo'),
  ('sesgo.confirmation-bias.name', 'es-MX', 'Sesgo de Confirmación', 'sesgo'),
  ('sesgo.confirmation-bias.definition', 'es-MX', 'Buscamos, notamos y recordamos la información que confirma nuestras creencias previas, ignorando la que las contradice.', 'sesgo'),
  ('sesgo.confirmation-bias.description', 'es-MX', 'El Sesgo de Confirmación es uno de los sesgos más perniciosos en finanzas. Según el CFA Institute, pertenece a la subcategoría de Perseverancia de Creencias: nos negamos a actualizar nuestras opiniones aunque los datos apunten en otra dirección. No es malicia — es que el Sistema 1 construye historias coherentes, no precisas.', 'sesgo'),
  ('sesgo.confirmation-bias.mechanism', 'es-MX', 'Daniel Kahneman explica que el Sistema 1 opera bajo WYSIATI ("What You See Is All There Is"): construye la mejor historia posible con la información disponible, ignorando lo que falta. La disonancia cognitiva hace doloroso enfrentar evidencia contradictoria.', 'sesgo'),
  ('sesgo.confirmation-bias.trapQuestion', 'es-MX', 'Estás convencido de que Bitcoin va a subir. ¿Qué buscas en Google? A) "Razones por las que Bitcoin subirá" o B) "Riesgos de invertir en Bitcoin hoy". — La mayoría elige A, buscando validar, no cuestionar.', 'sesgo'),
  ('sesgo.confirmation-bias.example.0.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.confirmation-bias.example.0.text', 'es-MX', 'Estás convencido de que Tesla va a subir. Lees solo artículos bullish, ignoras los que cuestionan su valuación. Tu "investigación" es en realidad validación.', 'sesgo'),
  ('sesgo.confirmation-bias.example.1.label', 'es-MX', 'Decisión personal', 'sesgo'),
  ('sesgo.confirmation-bias.example.1.text', 'es-MX', 'Decides que cierta ciudad es perfecta para vivir. Recuerdas las buenas noticias sobre ella y olvidas las malas.', 'sesgo'),
  ('sesgo.confirmation-bias.example.2.label', 'es-MX', 'Empresa', 'sesgo'),
  ('sesgo.confirmation-bias.example.2.text', 'es-MX', 'Un CEO comprometido con una estrategia ignora métricas que la cuestionan y enfatiza las que la apoyan en sus reportes trimestrales.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.0', 'es-MX', 'Practica el "empirismo negativo": intenta demostrar que tu idea es FALSA, no que es verdadera.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.1', 'es-MX', 'Steel-manning: construye el mejor argumento posible contra tu tesis antes de actuar.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.2', 'es-MX', 'Busca activamente artículos, analistas y datos que contradigan tu posición.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.3', 'es-MX', 'Antes de cualquier inversión, escribe explícitamente: ¿qué tendría que pasar para que esté equivocado?', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.situation', 'es-MX', 'Estás convencido de que una acción va a subir. ¿Qué buscas en Google?', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.0.text', 'es-MX', 'Razones por las que la acción subirá', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.0.reveal', 'es-MX', 'Sesgo: estás buscando validar, no investigar', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.1.text', 'es-MX', 'Riesgos y argumentos en contra de esa inversión', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.1.reveal', 'es-MX', 'Racional: primero busca la hipótesis nula — por qué podrías estar equivocado', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.situation', 'es-MX', 'Un político que no te agrada hace una gran donación a caridad. ¿Tu primer pensamiento?', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.0.text', 'es-MX', 'Seguro lo hace para evadir impuestos o limpiar su imagen', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.0.reveal', 'es-MX', 'Sesgo: interpretamos la misma evidencia diferente según nuestras creencias previas', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.1.text', 'es-MX', 'Finalmente hizo algo bueno, independientemente de sus motivaciones', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.1.reveal', 'es-MX', 'Racional: separamos los hechos de nuestros prejuicios previos', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.situation', 'es-MX', 'Llevas 6 meses invirtiendo en una empresa que no ha dado resultados. Encuentras un artículo que dice que el CEO es brillante.', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.0.text', 'es-MX', 'Esto confirma que mi análisis fue correcto — hay que esperar más', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.0.reveal', 'es-MX', 'Sesgo: usas información nueva para reforzar una posición que quizás debería revisarse', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.1.text', 'es-MX', 'Interesante, pero también busco artículos críticos del CEO antes de decidir', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.1.reveal', 'es-MX', 'Racional: el nuevo dato se evalúa junto a toda la evidencia disponible', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.question', 'es-MX', '¿Qué hace exactamente el sesgo de confirmación?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.0', 'es-MX', 'Buscar, interpretar y recordar información que confirma lo que ya creemos, ignorando lo que lo contradice', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.1', 'es-MX', 'Confirmar decisiones pasadas sin importar si fueron correctas o no', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.2', 'es-MX', 'Seguir la opinión de la mayoría para confirmar que nuestra decisión es correcta', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.question', 'es-MX', 'Un inversor convencido de que una empresa es excelente lee solo análisis positivos. ¿Cuál es el riesgo concreto?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.0', 'es-MX', 'Perder señales de alerta reales porque activamente evita información negativa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.1', 'es-MX', 'Sobreestimar el riesgo porque tiene demasiada información sobre la empresa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.2', 'es-MX', 'Seguir el efecto manada al leer los mismos análisis que todos', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.question', 'es-MX', '¿Cuál es el antídoto más efectivo contra el sesgo de confirmación?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.0', 'es-MX', 'Buscar activamente el mejor argumento en contra de tu propia tesis antes de decidir', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.1', 'es-MX', 'Leer más fuentes de información para tener una visión más completa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.2', 'es-MX', 'Esperar a que otros tomen la decisión primero para validar tu análisis', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.name', 'es-MX', 'Disponibilidad y Representatividad', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.definition', 'es-MX', 'Juzgamos probabilidades por qué tan fácil recordamos ejemplos (disponibilidad) o por a qué categoría se parece algo (representatividad).', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.description', 'es-MX', 'Estas dos heurísticas son atajos mentales del Sistema 1. La Disponibilidad nos lleva a sobreestimar la frecuencia de eventos memorables o recientes. La Representatividad nos hace clasificar situaciones por estereotipos, ignorando probabilidades estadísticas reales.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.mechanism', 'es-MX', 'Cuando enfrentamos una pregunta difícil (¿cuál es la probabilidad de X?), el cerebro la sustituye por una más fácil: ¿qué tan fácil recuerdo ejemplos de X? o ¿a qué categoría se parece X? Estas sustituciones son rápidas pero sistemáticamente erróneas.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.trapQuestion', 'es-MX', 'Linda tiene 31 años, es muy inteligente y activista social. ¿Qué es más probable? A) Cajera de banco. B) Cajera de banco y feminista. — La mayoría elige B, aunque matemáticamente A siempre es más probable que A+B.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.0.label', 'es-MX', 'Disponibilidad', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.0.text', 'es-MX', 'Después de ver las noticias sobre un robo, crees que la criminalidad aumentó drásticamente, aunque estadísticamente bajó. Lo memorable distorsiona tu percepción de frecuencia.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.1.label', 'es-MX', 'Representatividad', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.1.text', 'es-MX', 'Ves una empresa joven con fundador carismático y tecnología de moda — se parece a Apple en 1997. Inviertes sin revisar sus fundamentals. El parecido no es suficiente.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.2.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.2.text', 'es-MX', 'Después de tres meses de mercado alcista, crees que el rally continuará (disponibilidad reciente). Después de un crash, crees que todo seguirá cayendo.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.0', 'es-MX', 'Antes de estimar una probabilidad, pregunta: ¿cuál es la tasa base estadística real?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.1', 'es-MX', 'Desconfía de tu primera impresión cuando algo "se parece" a un patrón de éxito.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.2', 'es-MX', 'Los eventos dramáticos o recientes no son más probables — solo más memorables.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.3', 'es-MX', 'Busca datos duros antes de actuar sobre una intuición basada en lo que "recuerdas".', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.situation', 'es-MX', '¿Qué causa más muertes anuales en México?', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.disponibilidad-representatividad.question.0.option.0.text', 'es-MX', 'Homicidios', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.0.reveal', 'es-MX', 'Sesgo de disponibilidad: los homicidios aparecen más en noticias, parecen más frecuentes', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.1.text', 'es-MX', 'Diabetes y enfermedades crónicas', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.1.reveal', 'es-MX', 'Racional: enfermedades crónicas causan 5-10x más muertes, pero son menos "disponibles" en la memoria', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.situation', 'es-MX', 'Linda tiene 31 años, es inteligente y fue activista. ¿Qué es más probable que sea hoy?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.0.text', 'es-MX', 'Cajera de banco y feminista activa', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.0.reveal', 'es-MX', 'Sesgo de representatividad (Falacia de Conjunción): dos eventos juntos nunca pueden ser más probables que uno solo', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.1.text', 'es-MX', 'Cajera de banco', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.1.reveal', 'es-MX', 'Racional: P(A) siempre es ≥ P(A y B). El estereotipo nos distrae de la lógica básica', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.situation', 'es-MX', 'Una moneda justa cae cara 5 veces seguidas. ¿Qué esperas en el lanzamiento 6?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.0.text', 'es-MX', 'Cruz es más probable — ya es "hora" de que salga', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.0.reveal', 'es-MX', 'Falacia del jugador: cada lanzamiento es independiente. El pasado no influye en el futuro', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.1.text', 'es-MX', '50/50 — cada lanzamiento es independiente del anterior', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.1.reveal', 'es-MX', 'Racional: la moneda no tiene memoria. La representatividad nos hace ver patrones donde no existen', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.question', 'es-MX', '¿Qué determina qué tan probable nos parece un evento según el sesgo de disponibilidad?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.0', 'es-MX', 'La facilidad con la que ejemplos de ese evento vienen a nuestra mente', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.1', 'es-MX', 'La frecuencia estadística real con la que ocurre ese evento', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.2', 'es-MX', 'La cantidad de información que tenemos sobre ese evento', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.question', 'es-MX', 'Después de ver noticias sobre accidentes aéreos, muchas personas prefieren manejar. ¿Qué explica esta decisión?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.0', 'es-MX', 'La imagen vívida del accidente hace que el vuelo parezca más peligroso de lo que estadísticamente es', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.1', 'es-MX', 'Manejar es objetivamente más seguro que volar en todos los contextos', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.2', 'es-MX', 'Las personas hacen un análisis racional del riesgo basado en las noticias', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.question', 'es-MX', '¿Cuál es el impacto del sesgo de disponibilidad en decisiones de inversión?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.0', 'es-MX', 'Sobreponderar activos que estuvieron en las noticias recientemente, sin importar sus fundamentos', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.1', 'es-MX', 'Diversificar demasiado el portafolio por miedo a eventos poco probables', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.2', 'es-MX', 'Ignorar completamente los eventos recientes al tomar decisiones', 'sesgo'),
  ('sesgo.overconfidence.name', 'es-MX', 'Exceso de Confianza', 'sesgo'),
  ('sesgo.overconfidence.definition', 'es-MX', 'Tenemos una fe injustificada en nuestro propio razonamiento, juicios y habilidades cognitivas.', 'sesgo'),
  ('sesgo.overconfidence.description', 'es-MX', 'Kahneman afirma que si tuviera una varita mágica para eliminar un solo sesgo, eliminaría el exceso de confianza, ya que amplifica casi todos los demás. Se manifiesta como Ilusión de Conocimiento (creer que más información da más precisión) e Ilusión de Control (creer que podemos influir en lo aleatorio).', 'sesgo'),
  ('sesgo.overconfidence.mechanism', 'es-MX', 'El Sistema 1 construye historias coherentes con la información disponible. Como la historia es coherente, la sentimos como verdadera y confiable. No nos detenemos a preguntar qué datos nos faltan — la confianza no viene de la evidencia, sino de la coherencia del relato.', 'sesgo'),
  ('sesgo.overconfidence.trapQuestion', 'es-MX', 'En comparación con el promedio de tu grupo, ¿cómo calificarías tu capacidad para tomar decisiones financieras? A) Por encima del promedio. B) Promedio o por debajo. — En grupos educados, el 70-80% elige A, aunque estadísticamente es imposible.', 'sesgo'),
  ('sesgo.overconfidence.example.0.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.overconfidence.example.0.text', 'es-MX', 'Un estudio de Duke encontró que los CFOs de empresas dan rangos de confianza del 80% para el S&P500 que fallan el 67% de las veces. Prefieren parecer precisos aunque estén equivocados.', 'sesgo'),
  ('sesgo.overconfidence.example.1.label', 'es-MX', 'Trading', 'sesgo'),
  ('sesgo.overconfidence.example.1.text', 'es-MX', 'Los inversores individuales que operan más activamente obtienen menores rendimientos que los pasivos — la actividad excesiva es señal de exceso de confianza.', 'sesgo'),
  ('sesgo.overconfidence.example.2.label', 'es-MX', 'Personal', 'sesgo'),
  ('sesgo.overconfidence.example.2.text', 'es-MX', 'El 80% de las personas cree que sus habilidades para manejar están por encima del promedio. El 93% de estudiantes universitarios cree estar en el 50% superior de su clase.', 'sesgo'),
  ('sesgo.overconfidence.antidote.0', 'es-MX', 'Lleva un diario de decisiones: registra tus predicciones y mide tu precisión real versus percibida.', 'sesgo'),
  ('sesgo.overconfidence.antidote.1', 'es-MX', 'Practica rangos de incertidumbre amplios: si el 90% de tus estimaciones están en el rango, el rango es correcto.', 'sesgo'),
  ('sesgo.overconfidence.antidote.2', 'es-MX', 'El test del "Outside View": ¿cuál es la tasa base de éxito para situaciones similares a la tuya?', 'sesgo'),
  ('sesgo.overconfidence.antidote.3', 'es-MX', 'Busca activamente quién sabe más que tú sobre este tema — no como señal de debilidad, sino de inteligencia.', 'sesgo'),
  ('sesgo.overconfidence.question.0.situation', 'es-MX', 'Comparado con tu grupo, ¿cómo calificarías tu capacidad para tomar decisiones financieras racionales?', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.0.text', 'es-MX', 'Por encima del promedio (top 50%)', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.0.reveal', 'es-MX', 'Sesgo: estadísticamente, la mitad del grupo está por debajo. Si casi todos eligen esto, algo no cuadra', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.1.text', 'es-MX', 'Promedio o por debajo del promedio', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.1.reveal', 'es-MX', 'Racional: la humildad epistémica — saber lo que no sabes — es la base de buenas decisiones', 'sesgo'),
  ('sesgo.overconfidence.question.1.situation', 'es-MX', 'Llevas 3 años invirtiendo con buenos rendimientos. ¿A qué lo atribuyes?', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.0.text', 'es-MX', 'Mi estrategia y análisis — tomé las decisiones correctas', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.0.reveal', 'es-MX', 'Posible sesgo de autoatribución: los mercados alcistas hacen que todos parezcan genios', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.1.text', 'es-MX', 'Una mezcla de proceso sólido y condiciones favorables de mercado', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.1.reveal', 'es-MX', 'Racional: separar habilidad de suerte requiere un horizonte largo y análisis honesto', 'sesgo'),
  ('sesgo.overconfidence.question.2.situation', 'es-MX', 'El S&P500 está en 5,000. Tu estimación a 12 meses con 90% de confianza sería:', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.0.text', 'es-MX', '4,800 – 5,300 (rango preciso)', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.0.reveal', 'es-MX', 'Sesgo: los rangos estrechos fallan más del 60% de las veces en estudios de expertos', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.1.text', 'es-MX', '3,500 – 6,500 (rango amplio)', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.1.reveal', 'es-MX', 'Racional: un 90% de confianza real requiere un rango mucho más amplio en sistemas complejos', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.question', 'es-MX', '¿Cuál es la diferencia entre exceso de confianza e ilusión de conocimiento?', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.0', 'es-MX', 'La ilusión de conocimiento es creer que más información nos hace más precisos, aunque esa información sea irrelevante', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.1', 'es-MX', 'Son exactamente lo mismo: ambos describen sobreestimar las propias habilidades', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.2', 'es-MX', 'El exceso de confianza solo aplica a expertos; la ilusión de conocimiento a novatos', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.question', 'es-MX', 'Un trader revisa 20 indicadores antes de cada operación creyendo que por eso sus predicciones son más precisas. ¿Qué sesgo ilustra esto?', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.0', 'es-MX', 'Ilusión de conocimiento: más datos no garantizan mejores predicciones si no añaden información real', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.1', 'es-MX', 'Sesgo de confirmación: busca indicadores que confirmen su decisión previa', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.2', 'es-MX', 'Efecto halo: los indicadores sofisticados le dan una imagen de experto', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.question', 'es-MX', '¿Qué es el sesgo de autoatribución y cómo se relaciona con el exceso de confianza?', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.0', 'es-MX', 'Atribuir los éxitos a la propia habilidad y los fracasos a factores externos, reforzando la confianza sin fundamento real', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.1', 'es-MX', 'Creer que nuestras habilidades son superiores a las del promedio en todas las áreas', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.2', 'es-MX', 'Confiar demasiado en las recomendaciones de otros sin analizarlas', 'sesgo'),
  ('sesgo.self-attribution.name', 'es-MX', 'Auto-Atribución', 'sesgo'),
  ('sesgo.self-attribution.definition', 'es-MX', 'Atribuimos nuestros éxitos a nuestra habilidad y nuestros fracasos a factores externos.', 'sesgo'),
  ('sesgo.self-attribution.description', 'es-MX', 'El Sesgo de Auto-Atribución es el "combustible" del Exceso de Confianza. Juntos forman un ciclo peligroso: gano → fue mi habilidad → aprendo que soy bueno → pierdo → fue mala suerte → no aprendo nada. Este ciclo destruye nuestra capacidad de calibrar el riesgo real.', 'sesgo'),
  ('sesgo.self-attribution.mechanism', 'es-MX', 'El mecanismo es defensivo: el ego necesita proteger una autoimagen positiva. Atribuirse el mérito de los éxitos alimenta la autoestima; culpar al entorno de los fracasos protege de la autocrítica. El resultado es que nunca aprendemos de nuestros errores de manera sistemática.', 'sesgo'),
  ('sesgo.self-attribution.trapQuestion', 'es-MX', 'Tu cartera subió +25% este año. ¿Cuál fue el factor principal? A) Mi estrategia y selección (habilidad). B) Estuve en el sector correcto en el momento justo (suerte). — La mayoría elige A. ¿Y si la cartera hubiera bajado -25%?', 'sesgo'),
  ('sesgo.self-attribution.example.0.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.self-attribution.example.0.text', 'es-MX', 'Tu cartera subió 40% en 2021. Fue tu análisis brillante. En 2022 cayó 30%. Fue la Fed, el mercado, la guerra en Ucrania. El doble rasero impide aprendizaje real.', 'sesgo'),
  ('sesgo.self-attribution.example.1.label', 'es-MX', 'Empresa', 'sesgo'),
  ('sesgo.self-attribution.example.1.text', 'es-MX', 'Un CEO reporta ganancias récord: "nuestra estrategia brillante." Reporta pérdidas: "condiciones macroeconómicas adversas sin precedentes."', 'sesgo'),
  ('sesgo.self-attribution.example.2.label', 'es-MX', 'Personal', 'sesgo'),
  ('sesgo.self-attribution.example.2.text', 'es-MX', 'Pasaste un examen: estudiaste bien. Reprobaste: el profesor fue injusto o las preguntas eran ambiguas.', 'sesgo'),
  ('sesgo.self-attribution.antidote.0', 'es-MX', 'Diario de decisiones: registra ANTES de invertir tu razonamiento. Al revisar, evalúa el proceso, no solo el resultado.', 'sesgo'),
  ('sesgo.self-attribution.antidote.1', 'es-MX', 'Separar proceso de resultado: ¿fue una buena decisión dado lo que sabías entonces, independientemente del resultado?', 'sesgo'),
  ('sesgo.self-attribution.antidote.2', 'es-MX', 'Post-mortem honesto: cuando una inversión sale mal, identifica exactamente qué error cometiste, no qué factor externo falló.', 'sesgo'),
  ('sesgo.self-attribution.antidote.3', 'es-MX', 'Comparte tus análisis con alguien crítico antes de actuar — la exposición reduce el autoengaño.', 'sesgo'),
  ('sesgo.self-attribution.question.0.situation', 'es-MX', 'Tu inversión principal subió 35% este año. ¿A qué lo atribuyes principalmente?', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.0.text', 'es-MX', 'Mi análisis y timing — identifiqué bien la oportunidad', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.0.reveal', 'es-MX', 'Sesgo de autoatribución (Self-Enhancement): podría ser habilidad, pero ¿verificaste que no fue suerte de mercado?', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.1.text', 'es-MX', 'Una combinación de análisis razonable y condiciones favorables', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.1.reveal', 'es-MX', 'Racional: distinguir habilidad de suerte requiere múltiples ciclos de mercado, no un año', 'sesgo'),
  ('sesgo.self-attribution.question.1.situation', 'es-MX', 'Tu inversión principal cayó 25% inesperadamente. ¿Cómo lo describes en tu análisis?', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.0.text', 'es-MX', 'Riesgo sistémico / evento impredecible — fue externo a mi análisis', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.0.reveal', 'es-MX', 'Sesgo de autoprotección: ¿era realmente impredecible o ignoraste señales que no querías ver?', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.1.text', 'es-MX', 'Error de análisis — necesito identificar qué no vi correctamente', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.1.reveal', 'es-MX', 'Racional: incluso si el shock fue externo, ¿el sizing del riesgo era correcto?', 'sesgo'),
  ('sesgo.self-attribution.question.2.situation', 'es-MX', 'Un colega duplicó su inversión en criptomonedas este año. ¿Qué piensas?', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.0.text', 'es-MX', 'Es un inversor hábil que supo identificar la oportunidad', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.0.reveal', 'es-MX', 'Doble estándar: si fuera tu pérdida, ¿también sería habilidad? Aplicamos raseros distintos a éxitos ajenos y propios', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.1.text', 'es-MX', 'Asumió riesgos altos y las condiciones lo favorecieron', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.1.reveal', 'es-MX', 'Racional: consistencia en el rasero — aplica el mismo estándar a ti y a los demás', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.question', 'es-MX', '¿Qué es la aversión a la pérdida según Kahneman y Tversky?', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.option.0', 'es-MX', 'Perder $100 duele aproximadamente el doble que el placer de ganar $100', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.self-attribution.fixation.0.option.1', 'es-MX', 'Preferir siempre las inversiones más seguras independientemente del retorno', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.option.2', 'es-MX', 'Evitar cualquier decisión que pueda resultar en pérdida', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.question', 'es-MX', 'Un inversor mantiene una acción que bajó 40% esperando recuperarse pero vende rápido las que suben. ¿Cómo se llama este patrón?', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.0', 'es-MX', 'Efecto disposición: vender ganadoras pronto y mantener perdedoras demasiado tiempo', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.1', 'es-MX', 'Sesgo de confirmación: busca información que justifique mantener la acción', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.2', 'es-MX', 'Exceso de confianza: cree que puede predecir cuándo se recuperará', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.question', 'es-MX', '¿Qué es la aversión miope a la pérdida?', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.0', 'es-MX', 'Revisar el portafolio con tanta frecuencia que las pérdidas a corto plazo dominan las decisiones de largo plazo', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.1', 'es-MX', 'Negarse a invertir en activos que alguna vez tuvieron pérdidas históricas', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.2', 'es-MX', 'Preferir instrumentos de renta fija por encima de cualquier otro activo', 'sesgo'),
  ('sesgo.status-quo.name', 'es-MX', 'Sesgo de Status Quo', 'sesgo'),
  ('sesgo.status-quo.definition', 'es-MX', 'Preferimos mantener las cosas como están, incluso cuando cambiar sería objetivamente mejor.', 'sesgo'),
  ('sesgo.status-quo.description', 'es-MX', 'Descrito por Samuelson y Zeckhauser (1988), este sesgo surge del confort de lo conocido y del miedo al arrepentimiento. La inercia psicológica es poderosa: moverse del estado actual implica el riesgo de equivocarse activamente, mientras que quedarse quieto se percibe como "no hacer nada malo".', 'sesgo'),
  ('sesgo.status-quo.mechanism', 'es-MX', 'El Sistema 1 evalúa opciones en relación a un punto de referencia neutral — el Status Quo. Dado que las pérdidas pesan el doble que las ganancias (Aversión a la Pérdida), cualquier cambio se percibe como potencialmente desventajoso. La pereza del Sistema 2 completa el cuadro.', 'sesgo'),
  ('sesgo.status-quo.trapQuestion', 'es-MX', 'Te ofrecen cambiar tu portafolio actual por uno con mejores expectativas de rendimiento, pero requiere tomar acción activa. ¿Lo haces? — La mayoría dice que sí en frío. En la práctica, la inercia gana.', 'sesgo'),
  ('sesgo.status-quo.example.0.label', 'es-MX', 'Pensiones', 'sesgo'),
  ('sesgo.status-quo.example.0.text', 'es-MX', 'Cuando el plan de pensiones de una empresa cambia de opt-in a opt-out, la participación sube del 40% al 90%. El default lo es todo.', 'sesgo'),
  ('sesgo.status-quo.example.1.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.status-quo.example.1.text', 'es-MX', 'Un inversor hereda una cartera de bonos de su padre. Aunque las acciones tendrían mejor rendimiento esperado, mantiene los bonos porque "son lo que había".', 'sesgo'),
  ('sesgo.status-quo.example.2.label', 'es-MX', 'Empresa', 'sesgo'),
  ('sesgo.status-quo.example.2.text', 'es-MX', 'Una empresa sigue usando el mismo proveedor de software durante 10 años, aunque hay opciones mejores y más baratas, simplemente porque "siempre ha sido así".', 'sesgo'),
  ('sesgo.status-quo.antidote.0', 'es-MX', 'Re-enmarca la decisión: "¿Elegiría este portafolio si empezara de cero hoy?"', 'sesgo'),
  ('sesgo.status-quo.antidote.1', 'es-MX', 'Establece revisiones periódicas obligatorias — la inercia gana si no hay un trigger externo.', 'sesgo'),
  ('sesgo.status-quo.antidote.2', 'es-MX', 'Separa el apego emocional del análisis financiero: herencia, tradición y hábito no son argumentos financieros.', 'sesgo'),
  ('sesgo.status-quo.antidote.3', 'es-MX', 'El test de la acción inversa: ¿si hoy tuvieras lo que quieres cambiar, cambiarías a lo que tienes ahora?', 'sesgo'),
  ('sesgo.status-quo.question.0.situation', 'es-MX', 'Llevas 5 años con el mismo fondo de inversión. Aparece uno nuevo con mejor historial ajustado al riesgo. ¿Qué haces?', 'sesgo'),
  ('sesgo.status-quo.question.0.option.0.text', 'es-MX', 'Me quedo con el mío — ya lo conozco y cambiar da pereza', 'sesgo'),
  ('sesgo.status-quo.question.0.option.0.reveal', 'es-MX', 'Sesgo de status quo: la inercia y el confort de lo conocido impiden la decisión óptima', 'sesgo'),
  ('sesgo.status-quo.question.0.option.1.text', 'es-MX', 'Evalúo los dos con los mismos criterios y elijo el mejor sin importar cuál tenía antes', 'sesgo'),
  ('sesgo.status-quo.question.0.option.1.reveal', 'es-MX', 'Racional: la decisión se hace con los datos actuales, no con el peso de lo que ya tienes', 'sesgo'),
  ('sesgo.status-quo.question.1.situation', 'es-MX', 'Heredaste un portafolio de bonos conservadores de tu abuelo. Las acciones tendrían mejor rendimiento esperado para tu horizonte de 30 años. ¿Qué haces?', 'sesgo'),
  ('sesgo.status-quo.question.1.option.0.text', 'es-MX', 'Lo mantengo tal cual — fue su elección y cambiar se siente mal', 'sesgo'),
  ('sesgo.status-quo.question.1.option.0.reveal', 'es-MX', 'Sesgo de status quo + efecto dotación: el apego al origen del portafolio paraliza la optimización', 'sesgo'),
  ('sesgo.status-quo.question.1.option.1.text', 'es-MX', 'Evalúo si este portafolio es el adecuado para MI horizonte y perfil, independiente de su historia', 'sesgo'),
  ('sesgo.status-quo.question.1.option.1.reveal', 'es-MX', 'Racional: el origen del portafolio no determina su idoneidad para tu situación actual', 'sesgo'),
  ('sesgo.status-quo.question.2.situation', 'es-MX', 'Tu banco te cobra $1,200/año en comisiones. Otro banco ofrece las mismas condiciones sin comisión. ¿Qué haces?', 'sesgo'),
  ('sesgo.status-quo.question.2.option.0.text', 'es-MX', 'Me quedo — cambiar de banco es un proceso tedioso', 'sesgo'),
  ('sesgo.status-quo.question.2.option.0.reveal', 'es-MX', 'Sesgo de status quo: la fricción del cambio se percibe mayor que el beneficio real de $1,200 anuales', 'sesgo'),
  ('sesgo.status-quo.question.2.option.1.text', 'es-MX', 'Hago el cambio — $1,200 anuales son suficientes para dedicar 2 horas al proceso', 'sesgo'),
  ('sesgo.status-quo.question.2.option.1.reveal', 'es-MX', 'Racional: el costo del cambio (tiempo) se compara explícitamente con el beneficio (ahorro real)', 'sesgo'),
  ('sesgo.status-quo.fixation.0.question', 'es-MX', '¿Cuál es el mecanismo principal detrás del sesgo de status quo?', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.0', 'es-MX', 'La aversión a la pérdida hace que cualquier cambio parezca más costoso que los beneficios potenciales', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.1', 'es-MX', 'La falta de información sobre alternativas hace que mantener lo actual parezca más seguro', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.2', 'es-MX', 'El miedo a equivocarse hace que las personas eviten cualquier decisión activa', 'sesgo'),
  ('sesgo.status-quo.fixation.1.question', 'es-MX', 'Un experimento cambió el plan de pensiones de opt-in a opt-out. ¿Qué pasó con la participación?', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.0', 'es-MX', 'Subió drásticamente — el default determina más el comportamiento que la preferencia real', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.1', 'es-MX', 'Bajó — las personas rechazaron la inscripción automática por autonomía', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.2', 'es-MX', 'No cambió significativamente — las personas tomaron la misma decisión independiente del default', 'sesgo'),
  ('sesgo.status-quo.fixation.2.question', 'es-MX', '¿Cuál es la diferencia entre prudencia y sesgo de status quo?', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.0', 'es-MX', 'La prudencia se basa en análisis deliberado; el status quo se basa en inercia e incomodidad con el cambio', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.1', 'es-MX', 'La prudencia es un sesgo emocional; el status quo es una estrategia racional de bajo riesgo', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.2', 'es-MX', 'No hay diferencia real: ambos llevan a mantener la situación actual', 'sesgo'),
  ('sesgo.autocontrol.name', 'es-MX', 'Sesgo de Autocontrol', 'sesgo'),
  ('sesgo.autocontrol.definition', 'es-MX', 'No actuamos en pro de nuestros objetivos a largo plazo por falta de autodisciplina y preferencia por la gratificación inmediata.', 'sesgo'),
  ('sesgo.autocontrol.description', 'es-MX', 'El Sesgo de Autocontrol (CFA) y el Descuento Hiperbólico (Thaler) describen el mismo fenómeno: somos incapaces de ejecutar hoy lo que en teoría queremos para el futuro. No es un problema de conocimiento — sabemos que debemos ahorrar. Es un problema de voluntad bajo presión.', 'sesgo'),
  ('sesgo.autocontrol.mechanism', 'es-MX', 'Dan Ariely distingue el "yo en estado frío" (racional, planificador) del "yo en estado caliente" (impulsivo, bajo presión). En estado frío, elegimos virtuosamente. En estado caliente, el Sistema 1 toma el control. La "brecha de empatía" nos impide predecir cuánto diferirá nuestro yo caliente del yo frío.', 'sesgo'),
  ('sesgo.autocontrol.trapQuestion', 'es-MX', '¿Cuánto planeas ahorrar el próximo mes? Ahora: ¿cuánto ahorraste este mes? La diferencia entre estos dos números es tu "brecha de autocontrol".', 'sesgo'),
  ('sesgo.autocontrol.example.0.label', 'es-MX', 'Ahorro', 'sesgo'),
  ('sesgo.autocontrol.example.0.text', 'es-MX', 'Sabes que debes ahorrar el 20% de tu sueldo. Cada mes "este mes es la excepción" por alguna razón. Nunca ahorramos tanto como planeamos en frío.', 'sesgo'),
  ('sesgo.autocontrol.example.1.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.autocontrol.example.1.text', 'es-MX', 'Planeas no revisar tu portafolio más de una vez al mes. Pero cuando el mercado cae, entras a la app cada hora y terminas vendiendo en el peor momento.', 'sesgo'),
  ('sesgo.autocontrol.example.2.label', 'es-MX', 'Gasto', 'sesgo'),
  ('sesgo.autocontrol.example.2.text', 'es-MX', 'Decides no gastar en ropa este mes. Pero en el mall, ves una oferta "única" y el yo caliente gana.', 'sesgo'),
  ('sesgo.autocontrol.antidote.0', 'es-MX', 'Automatiza el ahorro: transfiere automáticamente antes de que el dinero llegue a tu cuenta corriente.', 'sesgo'),
  ('sesgo.autocontrol.antidote.1', 'es-MX', 'Usa la herramienta de Thaler: "Save More Tomorrow" — compromete hoy un % de tus futuros aumentos de sueldo.', 'sesgo'),
  ('sesgo.autocontrol.antidote.2', 'es-MX', 'Elimina la tentación del entorno: borra apps de trading si revisas en exceso; esconde tarjetas de crédito.', 'sesgo'),
  ('sesgo.autocontrol.antidote.3', 'es-MX', 'Contratos de compromiso (commitment devices): penalidades reales si no cumples tus metas.', 'sesgo'),
  ('sesgo.autocontrol.question.0.situation', 'es-MX', 'Recibes un bono de $10,000. Tienes una deuda de tarjeta al 20% de interés. ¿Qué haces?', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.0.text', 'es-MX', 'Pago la deuda inmediatamente — es el movimiento matemáticamente óptimo', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.0.reveal', 'es-MX', 'Racional: eliminar deuda al 20% es un retorno garantizado del 20%, difícil de superar', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.1.text', 'es-MX', 'Gasto la mitad en algo que quería y pago la mitad de la deuda', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.1.reveal', 'es-MX', 'Sesgo de autocontrol: el yo caliente interfiere con la decisión óptima del yo frío', 'sesgo'),
  ('sesgo.autocontrol.question.1.situation', 'es-MX', 'Llevas 4 horas en una reunión agotadora. Pasan snacks. ¿Qué eliges?', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.0.text', 'es-MX', 'El chocolate/galletas — estoy agotado y lo necesito', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.0.reveal', 'es-MX', 'Sesgo de autocontrol + Ego Depletion: el Sistema 2 está agotado y el Sistema 1 toma el control', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.1.text', 'es-MX', 'Frutos secos — aunque me cuesta, sigo mi plan de alimentación', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.1.reveal', 'es-MX', 'Autocontrol activo: el Sistema 2 ejercita la disciplina incluso bajo fatiga', 'sesgo'),
  ('sesgo.autocontrol.question.2.situation', 'es-MX', 'El mercado cayó 8% hoy. Tu portafolio bajó $15,000. ¿Qué haces?', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.0.text', 'es-MX', 'Reviso la app cada hora y eventualmente vendo para "detener las pérdidas"', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.0.reveal', 'es-MX', 'Sesgo de autocontrol: el malestar del yo caliente destruye el plan del yo frío', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.1.text', 'es-MX', 'Recuerdo mi plan de largo plazo y no hago nada hasta la revisión programada', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.1.reveal', 'es-MX', 'Racional: la aversión miope a la pérdida destruye retornos — el plan existe precisamente para momentos así', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.question', 'es-MX', '¿Qué es el descuento hiperbólico?', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.0', 'es-MX', 'La tendencia a preferir recompensas pequeñas e inmediatas sobre recompensas mayores en el futuro', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.1', 'es-MX', 'Descuentos que parecen atractivos pero tienen costos ocultos a largo plazo', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.2', 'es-MX', 'La incapacidad de calcular correctamente el valor del dinero en el tiempo', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.question', 'es-MX', 'Sabes que deberías ahorrar $2,000 al mes pero cada mes lo pospones. ¿Qué explica este patrón?', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.0', 'es-MX', 'Sesgo del presente: el yo futuro se siente lejano y abstracto; el placer de gastar hoy se siente concreto e inmediato', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.1', 'es-MX', 'Sesgo de status quo: prefieres mantener tus hábitos de gasto actuales', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.2', 'es-MX', 'Aversión a la pérdida: sientes que ahorrar es perder dinero disponible', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.question', 'es-MX', '¿Por qué los compromisos previos (precommitment) son efectivos contra este sesgo?', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.0', 'es-MX', 'Porque eliminan la decisión en el momento de tentación, cuando el Sistema 1 domina', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.1', 'es-MX', 'Porque aumentan la culpa cuando no cumplimos, lo que nos motiva más', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.2', 'es-MX', 'Porque hacen que el ahorro sea más visible y fácil de monitorear', 'sesgo'),
  ('sesgo.endowment-effect.name', 'es-MX', 'Efecto de Dotación', 'sesgo'),
  ('sesgo.endowment-effect.definition', 'es-MX', 'Valoramos más un activo simplemente porque lo poseemos.', 'sesgo'),
  ('sesgo.endowment-effect.description', 'es-MX', 'Descrito por Kahneman y Thaler, el Efecto de Dotación viola la teoría económica clásica: el precio al que estarías dispuesto a vender algo (WTA) debería ser igual al que pagarías por comprarlo (WTP). En la práctica, WTA siempre supera WTP — somos dueños sentimentales de nuestros activos.', 'sesgo'),
  ('sesgo.endowment-effect.mechanism', 'es-MX', 'Una vez que poseemos algo, dejarlo ir se siente como una pérdida. La aversión a la pérdida entra en juego: el dolor de perder la posesión supera el placer de ganar el dinero. Dan Ariely observó que empezamos a amar las cosas casi inmediatamente después de poseerlas, o incluso de imaginar que las poseemos.', 'sesgo'),
  ('sesgo.endowment-effect.trapQuestion', 'es-MX', 'Ganaste en un sorteo una entrada VIP de $1,500 para tu evento soñado. Alguien te ofrece $1,500 en efectivo por ella. ¿La vendes? — La mayoría dice no. Pero antes de ganarla, no habrías pagado $1,500 por ella.', 'sesgo'),
  ('sesgo.endowment-effect.example.0.label', 'es-MX', 'Inversión', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.endowment-effect.example.0.text', 'es-MX', 'Un inversor recibe acciones de su empresa como compensación. Aunque racionalmente sabe que está sobreexpuesto a un solo activo, no las vende porque "son mías, las gané yo".', 'sesgo'),
  ('sesgo.endowment-effect.example.1.label', 'es-MX', 'Inmuebles', 'sesgo'),
  ('sesgo.endowment-effect.example.1.text', 'es-MX', 'Los vendedores de casas siempre creen que su propiedad vale más de lo que dice el mercado. El apego emocional infla la valuación.', 'sesgo'),
  ('sesgo.endowment-effect.example.2.label', 'es-MX', 'Negociación', 'sesgo'),
  ('sesgo.endowment-effect.example.2.text', 'es-MX', 'En negociaciones, quien ya "tiene" algo (un contrato, un derecho) pide más para cederlo de lo que la contraparte pagaría para adquirirlo, bloqueando acuerdos eficientes.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.0', 'es-MX', 'Test del nuevo dinero: "¿Si tuviera este activo en efectivo hoy, compraría esta posición a este precio?"', 'sesgo'),
  ('sesgo.endowment-effect.antidote.1', 'es-MX', 'Valoración desde fuera: pide a alguien sin vínculo emocional que evalúe el activo.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.2', 'es-MX', 'Separar la historia del activo de su valor de mercado actual.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.3', 'es-MX', 'Revisión periódica forzada: "¿Qué tan objetivamente estoy valorando esto porque lo poseo?"', 'sesgo'),
  ('sesgo.endowment-effect.question.0.situation', 'es-MX', 'Tienes acciones de tu empresa que recibiste como bono. Representan el 40% de tu portafolio. ¿Qué haces?', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.0.text', 'es-MX', 'Las mantengo — son "mis" acciones, las gané, confío en la empresa', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.0.reveal', 'es-MX', 'Efecto de dotación: la posesión y el origen crean apego que nubla la evaluación de concentración de riesgo', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.1.text', 'es-MX', 'Evalúo si tener el 40% en una sola acción es prudente, independiente de su origen', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.1.reveal', 'es-MX', 'Racional: las acciones deben evaluarse como cualquier otra inversión, sin privilegio por su historia', 'sesgo'),
  ('sesgo.endowment-effect.question.1.situation', 'es-MX', 'Compraste un auto hace 3 años. Quieres venderlo. El mercado lo valúa en $180,000. ¿A qué precio lo pones?', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.0.text', 'es-MX', '$220,000 o más — mi auto está en perfecto estado y vale más que el promedio', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.0.reveal', 'es-MX', 'Efecto de dotación: todos los dueños creen que su auto es "especial" y está en mejor estado que el promedio', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.1.text', 'es-MX', '$180,000 o el precio de mercado — es lo que un comprador racional pagaría', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.1.reveal', 'es-MX', 'Racional: el mercado ya incorpora el "perfecto estado" en su valuación promedio', 'sesgo'),
  ('sesgo.endowment-effect.question.2.situation', 'es-MX', 'Ganaste en un sorteo una entrada a un concierto valorada en $2,000. Alguien te ofrece $2,000 en efectivo por ella. ¿La vendes?', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.0.text', 'es-MX', 'No — ya es mía y la experiencia vale más que el dinero', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.0.reveal', 'es-MX', 'Efecto de dotación: si antes de ganarla no habrías pagado $2,000, ¿por qué ahora vale más?', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.1.text', 'es-MX', 'Sí — si la entrada vale exactamente lo que me ofrecen, la decisión es neutra', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.1.reveal', 'es-MX', 'Racional: la propiedad no debería crear valor adicional si el precio es de mercado', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.question', 'es-MX', '¿Qué revela el experimento de las tazas de café de Kahneman sobre el efecto dotación?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.0', 'es-MX', 'Las personas piden más para vender algo que lo que pagarían por comprarlo, solo porque ya lo poseen', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.1', 'es-MX', 'Las personas valoran más los objetos de uso cotidiano que los de inversión', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.2', 'es-MX', 'El precio de mercado no refleja el valor real que los consumidores le dan a los productos', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.question', 'es-MX', 'Un inversor se niega a vender acciones heredadas de su abuelo aunque tengan mal desempeño. ¿Cómo opera el efecto dotación aquí?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.0', 'es-MX', 'La propiedad y el vínculo emocional inflan el valor percibido más allá del valor financiero real', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.1', 'es-MX', 'El sesgo de status quo le impide tomar decisiones activas sobre el portafolio', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.2', 'es-MX', 'La aversión a la pérdida le hace temer cristalizar la pérdida vendiendo', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.question', 'es-MX', '¿Cuál es la pregunta clave para neutralizar el efecto dotación en decisiones financieras?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.0', 'es-MX', '"Si no tuviera este activo hoy, ¿lo compraría a este precio?" — si la respuesta es no, hay que replantearse tenerlo', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.1', 'es-MX', '"¿Cuánto tiempo llevo con este activo?" — más tiempo justifica más apego', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.2', 'es-MX', '"¿Qué harían otros inversores con este activo?" — la comparación social neutraliza el sesgo', 'sesgo'),
  ('sesgo.halo-effect.name', 'es-MX', 'Efecto Halo', 'sesgo'),
  ('sesgo.halo-effect.definition', 'es-MX', 'Generalizamos un atributo positivo (o negativo) de una persona o empresa hacia todas sus demás características.', 'sesgo'),
  ('sesgo.halo-effect.description', 'es-MX', 'El Efecto Halo es una obra maestra del Sistema 1: ante la ausencia de información completa, usamos la emoción que nos produce un rasgo visible para "rellenar" los espacios en blanco. Si una empresa hace un producto que adoramos, asumimos que sus finanzas, gestión y perspectivas también son brillantes.', 'sesgo'),
  ('sesgo.halo-effect.mechanism', 'es-MX', 'Kahneman explica que el Sistema 1 detesta la ambigüedad y busca narrativas simples y coherentes. Ante la pregunta difícil "¿Es esta empresa una buena inversión?", sustituye por "¿Me gusta su producto?". La respuesta emocional llena los vacíos cognitivos.', 'sesgo'),
  ('sesgo.halo-effect.trapQuestion', 'es-MX', 'Tu teléfono favorito es de la marca X. Es rápido y hermoso. La empresa sale a bolsa. Tienes liquidez. ¿Qué haces? — Comprar porque el producto es genial es el Efecto Halo: producto ≠ acción.', 'sesgo'),
  ('sesgo.halo-effect.example.0.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.halo-effect.example.0.text', 'es-MX', 'Apple hace productos que amas. Sus acciones siempre valen más de lo que los fundamentals justifican porque el halo del producto contamina la valuación. "Buen producto = buena acción" es el Efecto Halo aplicado.', 'sesgo'),
  ('sesgo.halo-effect.example.1.label', 'es-MX', 'Contratación', 'sesgo'),
  ('sesgo.halo-effect.example.1.text', 'es-MX', 'Un candidato atractivo y bien vestido parece más competente en la entrevista, independientemente de sus respuestas técnicas. El físico irradia halo hacia la inteligencia.', 'sesgo'),
  ('sesgo.halo-effect.example.2.label', 'es-MX', 'Empresa', 'sesgo'),
  ('sesgo.halo-effect.example.2.text', 'es-MX', 'Un CEO carismático que habla bien en conferencias parece más capaz de ejecutar la estrategia, aunque los números digan otra cosa.', 'sesgo'),
  ('sesgo.halo-effect.antidote.0', 'es-MX', 'Separar explícitamente: "¿Me gusta el producto?" vs. "¿Es buena inversión la acción?"', 'sesgo'),
  ('sesgo.halo-effect.antidote.1', 'es-MX', 'Evalúa la empresa como si nunca hubieras usado su producto — ¿cómo ves los números?', 'sesgo'),
  ('sesgo.halo-effect.antidote.2', 'es-MX', 'Busca activamente debilidades en las empresas que más admiras.', 'sesgo'),
  ('sesgo.halo-effect.antidote.3', 'es-MX', 'El test del CEO feo: ¿evaluarías igual esta empresa si el CEO fuera antipático pero los números iguales?', 'sesgo'),
  ('sesgo.halo-effect.question.0.situation', 'es-MX', 'Eres fanático de una marca de autos de lujo. Acaban de sacar al mercado sus acciones. ¿Qué haces?', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.0.text', 'es-MX', 'Compro — si el producto es tan bueno, la empresa debe ser excelente', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.0.reveal', 'es-MX', 'Efecto Halo: la admiración por el producto contamina la evaluación financiera de la acción', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.1.text', 'es-MX', 'Analizo el ratio deuda/capital, márgenes y perspectivas como si no conociera la marca', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.1.reveal', 'es-MX', 'Racional: separar la experiencia como consumidor del análisis como inversor', 'sesgo'),
  ('sesgo.halo-effect.question.1.situation', 'es-MX', 'Un gestor de fondos es guapo, articula perfectamente y tiene un MBA de Harvard. ¿Qué peso le das a su historial de retornos?', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.0.text', 'es-MX', 'El MBA y la presencia me dan mucha confianza — reviso el historial de forma', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.0.reveal', 'es-MX', 'Efecto Halo: los atributos superficiales (apariencia, credenciales) contaminan la evaluación de lo que importa (resultados)', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.1.text', 'es-MX', 'El historial de retornos ajustados al riesgo es lo que determina mi decisión', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.1.reveal', 'es-MX', 'Racional: los retornos auditados son el único indicador que predice futuro desempeño con algo de validez', 'sesgo'),
  ('sesgo.halo-effect.question.2.situation', 'es-MX', 'Una empresa que hizo un producto que usas y adoras reporta pérdidas por tercer trimestre consecutivo. ¿Cómo reaccionas?', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.0.text', 'es-MX', 'Deben ser problemas temporales — es una empresa demasiado buena para fracasar', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.0.reveal', 'es-MX', 'Efecto Halo inverso: el amor por la marca crea resistencia a actualizar la visión ante evidencia negativa', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.1.text', 'es-MX', 'Reviso si hay razones fundamentales para las pérdidas y actualizo mi tesis', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.1.reveal', 'es-MX', 'Racional: los datos actuales pesan más que la historia emocional con la empresa', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.question', 'es-MX', '¿Qué es el efecto halo en el contexto de inversiones?', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.0', 'es-MX', 'Generalizar atributos positivos de una empresa a todos sus demás aspectos, formando una imagen distorsionada', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.1', 'es-MX', 'El brillo que genera un activo en todo el portafolio cuando sube de valor', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.2', 'es-MX', 'La tendencia a invertir en empresas conocidas porque su marca genera confianza', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.question', 'es-MX', 'Una empresa tech muy admirada lanza un producto en un mercado que no conoce. Los analistas la califican positivamente por inercia. ¿Qué sesgo opera?', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.0', 'es-MX', 'Efecto halo: el éxito pasado en tecnología contamina la evaluación de una aventura en un sector diferente', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.1', 'es-MX', 'Sesgo de disponibilidad: el éxito reciente de la empresa es fácil de recordar', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.2', 'es-MX', 'Representatividad: se parece a otras empresas que diversificaron exitosamente', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.question', 'es-MX', '¿Cuál es el antídoto más directo contra el efecto halo al evaluar una inversión?', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.0', 'es-MX', 'Analizar cada dimensión por separado — producto, finanzas, equipo — sin dejar que una contamine las demás', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.1', 'es-MX', 'Buscar opiniones de personas que no conozcan la empresa para evitar el sesgo', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.2', 'es-MX', 'Comparar la empresa con su competencia directa antes de evaluarla de forma aislada', 'sesgo'),
  ('sesgo.herding.name', 'es-MX', 'Efecto Manada', 'sesgo'),
  ('sesgo.herding.definition', 'es-MX', 'Tendemos a seguir las decisiones de la multitud, abandonando nuestro análisis propio.', 'sesgo'),
  ('sesgo.herding.description', 'es-MX', 'El Efecto Manada (Social Proof) es la tendencia a asumir que si muchos están haciendo algo, debe ser correcto. En inversiones, este sesgo alimenta burbujas (todos compran) y crashes (todos venden). Según el CFA, es un Error Cognitivo: el inversor falla en procesar información de manera independiente.', 'sesgo'),
  ('sesgo.herding.mechanism', 'es-MX', 'El cerebro sustituye una pregunta difícil ("¿Cuáles son los fundamentals de este activo?") por una fácil ("¿Están todos los demás comprando?"). Bajo incertidumbre, el consenso actúa como proxy de la verdad. Robert Cialdini explica que este mecanismo se amplifica con dos condiciones: incertidumbre y similitud.', 'sesgo'),
  ('sesgo.herding.trapQuestion', 'es-MX', 'Eres parte de un comité. Todos aprueban un proyecto con números frágiles. ¿Cómo actúas? — En frío, el 90% dice que votaría en contra. En la sala, la presión del grupo cambia el voto.', 'sesgo'),
  ('sesgo.herding.example.0.label', 'es-MX', 'Burbuja', 'sesgo'),
  ('sesgo.herding.example.0.text', 'es-MX', 'En 2021, millones compraron NFTs porque "todos los demás lo hacían". Nadie quería perderse el rally. El resultado fue una caída del 97% en muchos activos.', 'sesgo'),
  ('sesgo.herding.example.1.label', 'es-MX', 'Institucional', 'sesgo'),
  ('sesgo.herding.example.1.text', 'es-MX', 'Los gestores profesionales también sufren herding: es más seguro equivocarse con la mayoría ("todos perdimos") que equivocarse solo ("¿por qué tomaste esa posición?").', 'sesgo'),
  ('sesgo.herding.example.2.label', 'es-MX', 'FOMO', 'sesgo'),
  ('sesgo.herding.example.2.text', 'es-MX', 'Una acción sube 30% en una semana. El volumen de búsquedas en Google explota. Nuevos inversores entran justo cuando los informados están saliendo.', 'sesgo'),
  ('sesgo.herding.antidote.0', 'es-MX', 'Antes de cualquier decisión, escribe tu análisis ANTES de conocer la posición de los demás.', 'sesgo'),
  ('sesgo.herding.antidote.1', 'es-MX', 'El test del contrarian: ¿qué argumento haría el mejor inversor que va en dirección opuesta?', 'sesgo'),
  ('sesgo.herding.antidote.2', 'es-MX', 'El consenso es información, no verdad. Pregunta: ¿qué saben los que están comprando que yo no sé?', 'sesgo'),
  ('sesgo.herding.antidote.3', 'es-MX', 'Huye de las decisiones tomadas bajo urgencia y presión social — es precisamente cuando el herding ataca.', 'sesgo'),
  ('sesgo.herding.question.0.situation', 'es-MX', 'Un activo que no conoces subió 80% este mes. Todos tus amigos ya invirtieron. ¿Qué haces?', 'sesgo'),
  ('sesgo.herding.question.0.option.0.text', 'es-MX', 'Entro — si tanta gente está ganando, algo saben que yo no sé', 'sesgo'),
  ('sesgo.herding.question.0.option.0.reveal', 'es-MX', 'Efecto Manada: el consenso actúa como sustituto del análisis. Pero quienes entraron primero ya están saliendo', 'sesgo'),
  ('sesgo.herding.question.0.option.1.text', 'es-MX', 'Investigo los fundamentals antes de moverme, independiente de lo que hagan mis amigos', 'sesgo'),
  ('sesgo.herding.question.0.option.1.reveal', 'es-MX', 'Racional: cuando todos hablan de una inversión, suele ser tarde para entrar', 'sesgo'),
  ('sesgo.herding.question.1.situation', 'es-MX', 'En el comité de inversiones, 4 de 5 miembros aprueban un proyecto con proyecciones que te parecen optimistas. Eres el último en votar. ¿Qué haces?', 'sesgo'),
  ('sesgo.herding.question.1.option.0.text', 'es-MX', 'Voto a favor — si cuatro personas más inteligentes que yo lo aprobaron, algo ven', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.herding.question.1.option.0.reveal', 'es-MX', 'Herding institucional (Groupthink): los comités destruyen el valor de la información privada de cada miembro', 'sesgo'),
  ('sesgo.herding.question.1.option.1.text', 'es-MX', 'Voto en contra y explico mis dudas — el valor de estar en el comité es precisamente votar de forma independiente', 'sesgo'),
  ('sesgo.herding.question.1.option.1.reveal', 'es-MX', 'Racional: la diversidad de opiniones en un comité es su principal activo. Ceder al consenso la elimina', 'sesgo'),
  ('sesgo.herding.question.2.situation', 'es-MX', 'El mercado cayó 15% en dos semanas. Todos venden. Los medios hablan de "colapso histórico". ¿Qué haces con tu portafolio de largo plazo?', 'sesgo'),
  ('sesgo.herding.question.2.option.0.text', 'es-MX', 'Vendo también para evitar pérdidas mayores — si todos salen, algo grave está pasando', 'sesgo'),
  ('sesgo.herding.question.2.option.0.reveal', 'es-MX', 'Herding a la baja: las crisis generan el peor momento para seguir a la multitud — es cuando los informados compran', 'sesgo'),
  ('sesgo.herding.question.2.option.1.text', 'es-MX', 'Reviso si los fundamentals de mis posiciones cambiaron, no si el sentimiento del mercado cambió', 'sesgo'),
  ('sesgo.herding.question.2.option.1.reveal', 'es-MX', 'Racional: el precio y el valor divergen más en pánico. El herding vende cuando debería comprar', 'sesgo'),
  ('sesgo.herding.fixation.0.question', 'es-MX', '¿Por qué el efecto manada se intensifica en condiciones de incertidumbre?', 'sesgo'),
  ('sesgo.herding.fixation.0.option.0', 'es-MX', 'Porque bajo incertidumbre, el consenso actúa como sustituto del análisis — si todos lo hacen, debe ser correcto', 'sesgo'),
  ('sesgo.herding.fixation.0.option.1', 'es-MX', 'Porque en mercados volátiles la información individual pierde valor frente a la colectiva', 'sesgo'),
  ('sesgo.herding.fixation.0.option.2', 'es-MX', 'Porque la incertidumbre activa el Sistema 2 que busca validación social antes de decidir', 'sesgo'),
  ('sesgo.herding.fixation.1.question', 'es-MX', 'Los gestores profesionales de fondos también sufren efecto manada. ¿Por qué?', 'sesgo'),
  ('sesgo.herding.fixation.1.option.0', 'es-MX', 'Porque equivocarse junto a todos es profesionalmente menos costoso que equivocarse solo con una posición contraria', 'sesgo'),
  ('sesgo.herding.fixation.1.option.1', 'es-MX', 'Porque tienen acceso a la misma información y naturalmente llegan a las mismas conclusiones', 'sesgo'),
  ('sesgo.herding.fixation.1.option.2', 'es-MX', 'Porque los reguladores les exigen mantener portafolios similares al índice de referencia', 'sesgo'),
  ('sesgo.herding.fixation.2.question', 'es-MX', '¿Qué distingue al inversor que resiste el efecto manada del que cede?', 'sesgo'),
  ('sesgo.herding.fixation.2.option.0', 'es-MX', 'Escribir y documentar su análisis antes de conocer la posición del mercado o de otros inversores', 'sesgo'),
  ('sesgo.herding.fixation.2.option.1', 'es-MX', 'Tener más experiencia en mercados y conocer más casos históricos de burbujas', 'sesgo'),
  ('sesgo.herding.fixation.2.option.2', 'es-MX', 'Invertir en activos menos seguidos por el mercado donde hay menos presión de grupo', 'sesgo'),
  ('sesgo.optimism-bias.name', 'es-MX', 'Sesgo de Optimismo', 'sesgo'),
  ('sesgo.optimism-bias.definition', 'es-MX', 'Creemos sistemáticamente que tenemos menos probabilidad de vivir eventos negativos y más de vivir positivos que el promedio estadístico.', 'sesgo'),
  ('sesgo.optimism-bias.description', 'es-MX', 'El Sesgo de Optimismo es el "gemelo" del Exceso de Confianza. Juntos explican por qué los inversores asumen más riesgo del que deberían, los emprendedores subestiman el fracaso y los gestores prometen rendimientos imposibles. Nuestro ego necesita creer que el futuro será brillante y que somos excepcionales.', 'sesgo'),
  ('sesgo.optimism-bias.mechanism', 'es-MX', 'El Sistema 1 opera bajo WYSIATI: al planificar, se enfoca en el escenario ideal e ignora contingencias. La Falacia de Planificación (Kahneman) es su manifestación más clara: proyectos que siempre se entregan tarde y sobre presupuesto porque el plan asumió el mejor escenario.', 'sesgo'),
  ('sesgo.optimism-bias.trapQuestion', 'es-MX', 'Inicias un proyecto importante. ¿Defines el presupuesto y tiempo incluyendo un 30% de margen para imprevistos, o propones el escenario más optimista para "demostrar rentabilidad"? — En frío, todos dicen que incluyen margen. En la práctica, casi nadie lo hace.', 'sesgo'),
  ('sesgo.optimism-bias.example.0.label', 'es-MX', 'Falacia de planificación', 'sesgo'),
  ('sesgo.optimism-bias.example.0.text', 'es-MX', 'El 90% de los proyectos de construcción de infraestructura llegan tarde y sobre presupuesto. El optimismo de los planificadores es sistemático, no accidental.', 'sesgo'),
  ('sesgo.optimism-bias.example.1.label', 'es-MX', 'Emprendimiento', 'sesgo'),
  ('sesgo.optimism-bias.example.1.text', 'es-MX', 'El 90% de los emprendedores cree estar en el 10% que sobrevivirá. Estadísticamente, el 90% de las startups fracasan en 5 años.', 'sesgo'),
  ('sesgo.optimism-bias.example.2.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.optimism-bias.example.2.text', 'es-MX', 'Los inversores individuales estiman retornos promedios de 15-20% anual para sus portafolios, cuando el mercado históricamente da 8-10%.', 'sesgo'),
  ('sesgo.optimism-bias.antidote.0', 'es-MX', 'Outside View (Visión Externa): ¿cuál es la tasa base de éxito para proyectos similares al tuyo?', 'sesgo'),
  ('sesgo.optimism-bias.antidote.1', 'es-MX', 'Pre-mortem: imagina que tu plan falló — ¿cuáles fueron las 3 razones principales?', 'sesgo'),
  ('sesgo.optimism-bias.antidote.2', 'es-MX', 'Planifica con el escenario pesimista como base, no el optimista.', 'sesgo'),
  ('sesgo.optimism-bias.antidote.3', 'es-MX', 'Comparte tus planes con alguien que no tenga stake emocional para que identifique los puntos ciegos.', 'sesgo'),
  ('sesgo.optimism-bias.question.0.situation', 'es-MX', 'Estás lanzando un negocio. ¿Cómo defines tu presupuesto y timeline inicial?', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.0.text', 'es-MX', 'Propongo el escenario más rápido y barato — hay que mostrar rentabilidad atractiva', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.0.reveal', 'es-MX', 'Sesgo de optimismo / Falacia de Planificación: el 90% de proyectos llegan tarde y sobre presupuesto por exactamente esta razón', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.1.text', 'es-MX', 'Añado 30-40% de tiempo y capital extra sobre mi estimación base', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.1.reveal', 'es-MX', 'Racional: la "Visión Externa" muestra que los proyectos siempre cuestan más y tardan más de lo planeado', 'sesgo'),
  ('sesgo.optimism-bias.question.1.situation', 'es-MX', '¿Cuál crees que es la probabilidad de que tu próxima inversión te dé retornos por encima del mercado?', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.0.text', 'es-MX', 'Alta (70%+) — tengo información y análisis que el mercado no incorporó', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.0.reveal', 'es-MX', 'Sesgo de optimismo: los mercados son competitivos. La mayoría de inversores activos no supera al índice consistentemente', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.1.text', 'es-MX', 'Modesta (50% o menos) — los mercados son eficientes y la superioridad consistente es rara', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.1.reveal', 'es-MX', 'Racional: la humildad estadística es el punto de partida correcto. Superar al mercado es posible pero difícil', 'sesgo'),
  ('sesgo.optimism-bias.question.2.situation', 'es-MX', 'Tu startup tiene 18 meses de capital. Planificas el próximo fundraising. ¿Cuánto tiempo antes empiezas?', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.0.text', 'es-MX', '3-4 meses antes — con mis métricas no debería tardar tanto en cerrar', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.0.reveal', 'es-MX', 'Sesgo de optimismo: fundraisings toman en promedio 6-9 meses. La mayoría de founders empieza tarde por exactamente esta razón', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.1.text', 'es-MX', '9-12 meses antes — el proceso siempre tarda más de lo esperado', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.1.reveal', 'es-MX', 'Racional: planificar desde el escenario pesimista da margen para el mundo real', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.question', 'es-MX', '¿Qué es la Falacia de Planificación y quién la describió?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.0', 'es-MX', 'La tendencia sistemática a subestimar el tiempo, costo y riesgos de proyectos futuros, descrita por Kahneman', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.1', 'es-MX', 'El error de planificar con escenarios pesimistas que nunca se materializan, descrito por Thaler', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.2', 'es-MX', 'La dificultad de hacer planes a largo plazo cuando el futuro es muy incierto, descrita por Ariely', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.question', 'es-MX', 'El 90% de los conductores cree que maneja mejor que el promedio. ¿Qué ilustra esto?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.0', 'es-MX', 'Que sistemáticamente nos ubicamos por encima del promedio en habilidades, lo cual es estadísticamente imposible para la mayoría', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.1', 'es-MX', 'Que las personas mienten sobre sus habilidades para parecer mejores ante los demás', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.2', 'es-MX', 'Que el optimismo es una estrategia racional para mantener la motivación', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.question', 'es-MX', '¿Qué es el "outside view" (visión externa) y por qué combate el sesgo de optimismo?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.0', 'es-MX', 'Preguntar cuál es la tasa base de éxito para proyectos similares al tuyo, en lugar de enfocarte solo en tu caso particular', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.1', 'es-MX', 'Pedir la opinión de personas externas a tu equipo antes de tomar una decisión importante', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.2', 'es-MX', 'Analizar los datos históricos del mercado en lugar de proyecciones futuras', 'sesgo'),
  ('sesgo.authority-bias.name', 'es-MX', 'Sesgo de Autoridad', 'sesgo'),
  ('sesgo.authority-bias.definition', 'es-MX', 'Damos demasiado peso a la opinión de figuras que percibimos como expertos, sin cuestionar si realmente lo son.', 'sesgo'),
  ('sesgo.authority-bias.description', 'es-MX', 'El Sesgo de Autoridad (Cialdini) es uno de sus seis Principios de Influencia: estamos programados para obedecer a figuras de autoridad como atajo cognitivo. En finanzas, esto nos hace abandonar nuestro análisis ante cualquier figura con credenciales, título o confianza aparente.', 'sesgo'),
  ('sesgo.authority-bias.mechanism', 'es-MX', 'El cerebro está biológicamente diseñado para usar la autoridad como señal de fiabilidad — evolutivamente ahorró energía y tiempo. El Sistema 1 convierte credenciales (título, ropa, confianza) en permiso para no pensar. El problema: las credenciales no siempre predicen competencia, y los expertos tienen conflictos de interés.', 'sesgo'),
  ('sesgo.authority-bias.trapQuestion', 'es-MX', 'Un célebre Nobel de Economía publica un modelo de inversión innovador. ¿Qué haces? A) Revisar el modelo con cautela buscando vulnerabilidades. B) Adoptarlo — su nivel garantiza resultados. — LTCM tenía dos Nobeles y quebró espectacularmente.', 'sesgo'),
  ('sesgo.authority-bias.example.0.label', 'es-MX', 'Finanzas', 'sesgo'),
  ('sesgo.authority-bias.example.0.text', 'es-MX', 'Madoff manejó el mayor fraude financiero de la historia ($65B) durante décadas. Los inversores nunca auditaron sus estrategias porque su autoridad como ex-presidente del NASDAQ era suficiente señal.', 'sesgo'),
  ('sesgo.authority-bias.example.1.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.authority-bias.example.1.text', 'es-MX', 'Un Nobel de Economía publica un modelo. Los fondos lo adoptan sin cuestionar sus supuestos. LTCM quebró con dos nobeles en el equipo.', 'sesgo'),
  ('sesgo.authority-bias.example.2.label', 'es-MX', 'Redes sociales', 'sesgo'),
  ('sesgo.authority-bias.example.2.text', 'es-MX', 'Influencers financieros con millones de seguidores mueven mercados. La audiencia asume que quien tiene muchos seguidores sabe más.', 'sesgo'),
  ('sesgo.authority-bias.antidote.0', 'es-MX', 'Separa las credenciales del argumento: ¿el argumento se sostiene por sí solo, sin importar quién lo dice?', 'sesgo'),
  ('sesgo.authority-bias.antidote.1', 'es-MX', 'Pregunta siempre: ¿qué incentivos tiene esta persona para darme este consejo?', 'sesgo'),
  ('sesgo.authority-bias.antidote.2', 'es-MX', 'Busca la opinión de expertos en el otro lado — si solo escuchas un lado, estás bajo el sesgo.', 'sesgo'),
  ('sesgo.authority-bias.antidote.3', 'es-MX', 'La prueba del historial auditado: ¿cuál es el track record real de esta persona en situaciones similares?', 'sesgo'),
  ('sesgo.authority-bias.question.0.situation', 'es-MX', 'Un famoso gestor de fondos con 30 años de experiencia recomienda una acción en televisión. ¿Qué haces?', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.0.text', 'es-MX', 'Si él lo dice con tanto conviction, debe saber algo — compro', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.0.reveal', 'es-MX', 'Sesgo de autoridad: los expertos también se equivocan. ¿Tiene posición en esa acción? ¿Cuál es su track record reciente?', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.1.text', 'es-MX', 'Uso su tesis como punto de partida para mi propio análisis, no como conclusión', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.1.reveal', 'es-MX', 'Racional: la autoridad puede señalar ideas interesantes, pero no reemplaza el análisis propio', 'sesgo'),
  ('sesgo.authority-bias.question.1.situation', 'es-MX', 'Tu asesor bancario — corbata, oficina lujosa, MBA — te recomienda un fondo de inversión con comisiones del 2.5% anual. ¿Qué haces?', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.0.text', 'es-MX', 'Si me lo recomienda el banco, debe ser bueno — contrato', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.0.reveal', 'es-MX', 'Sesgo de autoridad: los asesores bancarios tienen incentivos para recomendar productos del banco. El 2.5% es altísimo', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.1.text', 'es-MX', 'Pregunto qué comisión recibe por recomendarlo, comparo con ETFs y decido con información', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.1.reveal', 'es-MX', 'Racional: en finanzas, los incentivos del asesor frecuentemente divergen de tu interés', 'sesgo'),
  ('sesgo.authority-bias.question.2.situation', 'es-MX', 'Un influencer con 3M de seguidores, que parece muy exitoso, recomienda "la criptomoneda del momento". ¿Qué haces?', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.0.text', 'es-MX', 'Si 3M de personas lo siguen, algo sabe — al menos meto un poco', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.0.reveal', 'es-MX', 'Sesgo de autoridad + herding: los seguidores son prueba social, no de competencia. Muchos influencers fueron pagados para promover', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.1.text', 'es-MX', 'Investigo si tiene posición en ese activo, cuál es su historial real y los fundamentos del proyecto', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.1.reveal', 'es-MX', 'Racional: los incentivos y el historial son lo que importa, no los seguidores ni la apariencia de éxito', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.question', 'es-MX', '¿Qué es la negligencia de la tasa base en el sesgo de representatividad?', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.0', 'es-MX', 'Ignorar la probabilidad estadística real de que algo ocurra porque un caso concreto parece muy representativo', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.1', 'es-MX', 'No considerar los costos base al calcular el retorno de una inversión', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.2', 'es-MX', 'Subestimar la importancia de las tasas de interés en decisiones financieras', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.question', 'es-MX', 'Una startup tiene un fundador joven con hoodie y oficina en Silicon Valley. La describes como "la próxima Apple". ¿Qué sesgo opera?', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.0', 'es-MX', 'Representatividad: el parecido superficial con el estereotipo de empresa exitosa sustituye el análisis real', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.1', 'es-MX', 'Efecto halo: los atributos positivos del fundador se transfieren a la empresa', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.2', 'es-MX', 'Sesgo de disponibilidad: recuerdas fácilmente casos de startups exitosas similares', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.authority-bias.fixation.2.question', 'es-MX', '¿Qué hace el cerebro cuando aplica el sesgo de representatividad?', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.0', 'es-MX', 'Clasifica algo nuevo según su parecido con un estereotipo, ignorando la probabilidad estadística real', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.1', 'es-MX', 'Representa mentalmente los escenarios futuros para tomar mejores decisiones', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.2', 'es-MX', 'Usa la experiencia pasada de forma sistemática y precisa para evaluar situaciones nuevas', 'sesgo'),
  ('sesgo.regret-aversion.name', 'es-MX', 'Aversión al Arrepentimiento', 'sesgo'),
  ('sesgo.regret-aversion.definition', 'es-MX', 'Evitamos tomar decisiones por miedo a que el resultado sea malo y nos haga sentir responsables de la pérdida.', 'sesgo'),
  ('sesgo.regret-aversion.description', 'es-MX', 'La Aversión al Arrepentimiento es distinta de la Aversión al Riesgo clásica: no es miedo a perder dinero, es miedo a sentirte responsable de haberlo perdido. Esto lleva a dos comportamientos opuestos: parálisis (no hacer nada para no equivocarse activamente) y comportamiento de manada (si todos se equivocan, no es tu culpa).', 'sesgo'),
  ('sesgo.regret-aversion.mechanism', 'es-MX', 'Kahneman explica que el arrepentimiento es una emoción contrafactual: el cerebro simula la realidad alternativa ("si tan solo hubiera…"). El dolor es más intenso cuando la pérdida resulta de una acción que tomamos que de una omisión. Esto crea una asimetría que paraliza la toma de decisiones.', 'sesgo'),
  ('sesgo.regret-aversion.trapQuestion', 'es-MX', 'Fondo A perdió 10% manteniendo su estrategia estándar. Fondo B perdió 10% tras intentar una nueva estrategia. ¿A cuál gestor despides? — La mayoría despide al de B, aunque el resultado es idéntico. Castigamos más el error por acción que por omisión.', 'sesgo'),
  ('sesgo.regret-aversion.example.0.label', 'es-MX', 'Efecto disposición', 'sesgo'),
  ('sesgo.regret-aversion.example.0.text', 'es-MX', 'Un inversor mantiene una acción perdedora durante años porque venderla "haría real" la pérdida y tendría que admitir que se equivocó. Vende las ganadoras para asegurar ganancias antes de que "se vayan".', 'sesgo'),
  ('sesgo.regret-aversion.example.1.label', 'es-MX', 'Manada', 'sesgo'),
  ('sesgo.regret-aversion.example.1.text', 'es-MX', 'Un gestor invierte en lo mismo que todos sus colegas. Si pierde, "todos perdimos" — el arrepentimiento se diluye. Si hubiera tomado una posición contraria y perdido, habría sido culpa exclusivamente suya.', 'sesgo'),
  ('sesgo.regret-aversion.example.2.label', 'es-MX', 'Inacción', 'sesgo'),
  ('sesgo.regret-aversion.example.2.text', 'es-MX', 'Una persona con dinero en efectivo por un año que "espera el momento correcto" para invertir. El miedo al arrepentimiento de entrar en el momento equivocado supera el costo de oportunidad de no estar invertido.', 'sesgo'),
  ('sesgo.regret-aversion.antidote.0', 'es-MX', 'Distinguir proceso de resultado: ¿fue una buena decisión dado lo que sabías, aunque el resultado fuera malo?', 'sesgo'),
  ('sesgo.regret-aversion.antidote.1', 'es-MX', 'Re-enmarcar el inmovilismo: no decidir también es una decisión — y también puede generar arrepentimiento.', 'sesgo'),
  ('sesgo.regret-aversion.antidote.2', 'es-MX', 'Regla del "10-10-10" (Suzy Welch): ¿cómo te sentirás sobre esta decisión en 10 minutos, 10 meses, 10 años?', 'sesgo'),
  ('sesgo.regret-aversion.antidote.3', 'es-MX', 'Portafolio de "arrepentimiento mínimo": diseña tu estrategia para que puedas vivir con el peor escenario posible.', 'sesgo'),
  ('sesgo.regret-aversion.question.0.situation', 'es-MX', 'Fondo A perdió -10% manteniendo su estrategia conservadora de siempre. Fondo B perdió -10% tras cambiar a una estrategia nueva. ¿A quién despides?', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.0.text', 'es-MX', 'Al gestor de Fondo B — intentó algo nuevo y falló', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.0.reveal', 'es-MX', 'Sesgo de omisión: castigamos más los errores por acción que por inacción, aunque el resultado sea idéntico', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.1.text', 'es-MX', 'A ninguno / Son equivalentes — el resultado fue el mismo', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.1.reveal', 'es-MX', 'Racional: el resultado fue idéntico. Si Fondo B habría ganado con la nueva estrategia, habrías felicitado al gestor por la misma decisión', 'sesgo'),
  ('sesgo.regret-aversion.question.1.situation', 'es-MX', 'Tienes $500,000 en efectivo esperando "el momento correcto" para invertir. Llevas 14 meses esperando. ¿Qué haces?', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.0.text', 'es-MX', 'Sigo esperando — si entro y el mercado cae, me voy a arrepentir de no haber esperado', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.0.reveal', 'es-MX', 'Aversión al arrepentimiento por acción: pero ¿cuánto costó de oportunidad ese año y medio en efectivo?', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.1.text', 'es-MX', 'Entro de forma escalonada — el costo de oportunidad de esperar también genera arrepentimiento', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.1.reveal', 'es-MX', 'Racional: la inacción también genera arrepentimiento futuro. El dollar-cost averaging reduce el dolor de "entrar en el tope"', 'sesgo'),
  ('sesgo.regret-aversion.question.2.situation', 'es-MX', 'Necesitas liquidar una posición urgentemente. Tienes: Acción A (+20%) y Acción B (-25%). Ambas con igual potencial a futuro. ¿Cuál vendes?', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.0.text', 'es-MX', 'Vendo la A (+20%) — aseguro la ganancia y no "hago real" la pérdida en B', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.0.reveal', 'es-MX', 'Efecto disposición / Aversión al arrepentimiento: vender la ganadora y mantener la perdedora es el sesgo clásico de Shefrin & Statman', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.1.text', 'es-MX', 'Evalúo cuál tiene mejor perspectiva a futuro y vendo la que menos me convence', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.1.reveal', 'es-MX', 'Racional: el precio de entrada es irrelevante para la decisión de hoy. Solo importa el potencial futuro', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.question', 'es-MX', '¿Cuál es la diferencia entre un error de comisión y uno de omisión en la aversión al arrepentimiento?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.0', 'es-MX', 'El error de comisión es actuar y que salga mal; el de omisión es no actuar y perder una oportunidad — el primero duele más', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.1', 'es-MX', 'El error de comisión es no hacer nada; el de omisión es actuar sin suficiente información', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.2', 'es-MX', 'Ambos generan el mismo nivel de arrepentimiento según las investigaciones de Kahneman', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.question', 'es-MX', 'Un inversor no vende una posición perdedora porque "si vendo y sube, no me lo voy a perdonar". ¿Qué sesgo explica la parálisis?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.0', 'es-MX', 'Aversión al arrepentimiento: el miedo al arrepentimiento futuro pesa más que el análisis racional presente', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.1', 'es-MX', 'Efecto dotación: sobrevalora la posición porque ya la posee', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.2', 'es-MX', 'Sesgo de status quo: prefiere no tomar decisiones activas', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.question', 'es-MX', '¿Cómo el comportamiento de manada puede ser una forma de gestionar el arrepentimiento?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.0', 'es-MX', 'Si perdemos dinero siguiendo a todos, el arrepentimiento es menor porque todos perdieron — equivocarse solo duele más', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.1', 'es-MX', 'Seguir a la manada reduce el arrepentimiento porque la decisión colectiva siempre es más precisa', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.2', 'es-MX', 'El comportamiento de manada elimina el arrepentimiento porque distribuye la responsabilidad legalmente', 'sesgo'),
  ('sesgo.escalation-commitment.name', 'es-MX', 'Escalada de Compromiso', 'sesgo'),
  ('sesgo.escalation-commitment.definition', 'es-MX', 'Continuamos invirtiendo en un proyecto o posición porque ya invertimos en él, no porque tenga potencial futuro.', 'sesgo'),
  ('sesgo.escalation-commitment.description', 'es-MX', 'La Falacia del Costo Hundido es una combinación de Error Cognitivo (Contabilidad Mental, Encuadre Estrecho) y Sesgo Emocional (Aversión a la Pérdida, Aversión al Arrepentimiento). Es el sesgo que mantiene proyectos fallidos vivos, carteras llenas de posiciones perdedoras y personas en relaciones que ya no funcionan.', 'sesgo'),
  ('sesgo.escalation-commitment.mechanism', 'es-MX', 'Kahneman explica que nos negamos a "cerrar la cuenta mental" con saldo negativo. La aversión a la pérdida hace que invertir más parezca la única manera de "recuperar". La responsabilidad personal amplifica el efecto: cuanto más fuimos los creadores de la decisión original, más difícil es abandonarla.', 'sesgo'),
  ('sesgo.escalation-commitment.trapQuestion', 'es-MX', 'Eres consultor externo. Un cliente lleva años financiando un proyecto que ya no tiene demanda. ¿Qué recomiendas? — En frío, el 90% dice "cancelar". Pero cuando es TU proyecto, con TU dinero, la respuesta cambia.', 'sesgo'),
  ('sesgo.escalation-commitment.example.0.label', 'es-MX', 'Empresarial (Concorde)', 'sesgo'),
  ('sesgo.escalation-commitment.example.0.text', 'es-MX', 'Los gobiernos de Francia y Reino Unido siguieron financiando el Concorde durante años después de saber que era económicamente inviable. No podían admitir el error.', 'sesgo'),
  ('sesgo.escalation-commitment.example.1.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.escalation-commitment.example.1.text', 'es-MX', 'Una acción que compraste a $100 está en $30. La sigues manteniendo y comprando más, no porque creas en la empresa, sino porque "no puedes vender a ese precio".', 'sesgo'),
  ('sesgo.escalation-commitment.example.2.label', 'es-MX', 'Personal', 'sesgo'),
  ('sesgo.escalation-commitment.example.2.text', 'es-MX', 'Llevas 2 años en un posgrado que no te gusta y no es relevante para tu carrera. Sigues porque "ya invertí mucho tiempo y dinero".', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.0', 'es-MX', 'Test del Nuevo CEO: "¿Si yo llegara hoy sin historia con este proyecto, continuaría o lo cancelaría?"', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.1', 'es-MX', 'Reformular la pregunta: "¿Cuánto invertiría HOY en esto si empezara de cero?"', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.2', 'es-MX', 'Stop-loss predefinidos: antes de invertir, define cuándo y bajo qué condiciones saldrías.', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.3', 'es-MX', 'Re-etiquetar el fracaso: la pérdida ya ocurrió — la pregunta es solo qué hacer hacia adelante.', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.situation', 'es-MX', 'Compraste acciones de una empresa a $100. Hoy valen $40. Llevas 8 meses esperando que se recupere. ¿Qué preguntas te haces?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.0.text', 'es-MX', '¿Cómo puedo recuperar los $60 que perdí?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.0.reveal', 'es-MX', 'Escalada de compromiso: los $60 ya se perdieron. La pregunta correcta es sobre el futuro, no el pasado', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.1.text', 'es-MX', '¿Si tuviera $40 en efectivo hoy, compraría esta acción a $40?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.1.reveal', 'es-MX', 'Racional: este es el Test del Nuevo CEO — la decisión debe basarse en el futuro, no en recuperar el pasado', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.situation', 'es-MX', 'Tu startup lleva 18 meses sin tracción. Ya gastaste $800K. Los clientes no adoptan el producto. Tienes $200K en caja. ¿Qué haces?', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.0.text', 'es-MX', 'Inyecto los $200K restantes — no puedo darme por vencido después de tanto sacrificio', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.0.reveal', 'es-MX', 'Escalada de compromiso: los $800K ya no se pueden recuperar. La pregunta es si los $200K tienen mejor retorno en este proyecto o en otro', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.1.text', 'es-MX', 'Evalúo si hay evidencia nueva que justifique continuar, o si es momento de un pivot o cierre', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.1.reveal', 'es-MX', 'Racional: la decisión se hace con los datos actuales, no con el peso emocional del pasado', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.situation', 'es-MX', 'Llevas 3 años en un proyecto laboral que te tiene infeliz. Tu lógica para quedarte es "ya invertí mucho aquí". ¿Es un buen argumento?', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.0.text', 'es-MX', 'Sí — es válido considerar todo lo que construí antes de renunciar', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.0.reveal', 'es-MX', 'Escalada de compromiso: lo que ya invertiste no cambia lo que ganarás o perderás hacia adelante. La decisión se hace desde hoy', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.1.text', 'es-MX', 'No — lo que ya invertí no recuperaré. La pregunta es qué quiero construir a partir de hoy', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.1.reveal', 'es-MX', 'Racional: el tiempo pasado no se puede recuperar. Solo el tiempo futuro está en juego', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.question', 'es-MX', '¿Qué distingue la escalada de compromiso de simplemente ser perseverante?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.0', 'es-MX', 'La escalada ignora nueva evidencia negativa y continúa por lo ya invertido; la perseverancia responde a fundamentos reales', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.1', 'es-MX', 'La escalada solo ocurre en grandes inversiones; la perseverancia aplica a decisiones cotidianas', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.2', 'es-MX', 'La perseverancia es siempre racional; la escalada siempre es irracional sin excepción', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.question', 'es-MX', 'Un CEO lleva 3 años defendiendo una división que pierde dinero. Los datos empeoran cada trimestre. ¿Qué sesgos combinados explican su comportamiento?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.0', 'es-MX', 'Escalada de compromiso + aversión a la pérdida + ilusión de control: no puede admitir el fracaso y cree que puede revertirlo', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.1', 'es-MX', 'Exceso de confianza + efecto manada: confía en que el mercado eventualmente validará su estrategia', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.2', 'es-MX', 'Sesgo de confirmación + representatividad: interpreta los datos negativos como casos excepcionales', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.question', 'es-MX', '¿Qué es la "táctica del nuevo CEO" como antídoto a la escalada?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.0', 'es-MX', 'Preguntarse: "Si llegara hoy sin historia en este proyecto, ¿tomaría esta misma decisión?" — juzgar sin equipaje emocional', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.1', 'es-MX', 'Contratar un consultor externo que no tenga vínculos con el proyecto para que evalúe objetivamente', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.2', 'es-MX', 'Establecer desde el inicio criterios claros de éxito y fracaso que no puedan modificarse después', 'sesgo'),
  ('sesgo.anclaje.name', 'es-MX', 'Anclaje y Ajuste', 'sesgo'),
  ('sesgo.anclaje.definition', 'es-MX', 'Dependemos excesivamente de un valor inicial (el "ancla") para hacer estimaciones, ajustando insuficientemente desde ese punto.', 'sesgo'),
  ('sesgo.anclaje.description', 'es-MX', 'El sesgo de Anclaje, descrito por Kahneman y Tversky, muestra que cualquier número que veamos primero actúa como punto de referencia que contamina todas las estimaciones posteriores. Dan Ariely lo llama "Coherencia Arbitraria": el primer precio que vemos se convierte en el estándar mental, incluso si fue completamente aleatorio.', 'sesgo'),
  ('sesgo.anclaje.mechanism', 'es-MX', 'El Sistema 1 es insuficientemente crítico con el ancla inicial. El ajuste desde el ancla siempre es insuficiente porque nos detenemos en el primer valor "plausible". No importa si el ancla es relevante o ridícula — su efecto persiste.', 'sesgo'),
  ('sesgo.anclaje.trapQuestion', 'es-MX', '¿Cuánta gente hay en Turquía? Ahora: primero dime, ¿hay más o menos de 10 millones? — Después de pensar en 10M, tu respuesta será diferente que si te hubiera dicho 100M primero. El número arbitrario te ancló.', 'sesgo'),
  ('sesgo.anclaje.example.0.label', 'es-MX', 'Negociación', 'sesgo'),
  ('sesgo.anclaje.example.0.text', 'es-MX', 'En una negociación salarial, quien pone el primer número sobre la mesa ancla toda la discusión. El que responde siempre ajusta desde ese punto, no desde su valor real.', 'sesgo'),
  ('sesgo.anclaje.example.1.label', 'es-MX', 'Inversión', 'sesgo'),
  ('sesgo.anclaje.example.1.text', 'es-MX', 'Una acción que compraste a $200 y ahora vale $80. Tu ancla es $200 y percibes $80 como "barata", aunque $80 pueda ser todavía cara según los fundamentals actuales.', 'sesgo'),
  ('sesgo.anclaje.example.2.label', 'es-MX', 'Precios', 'sesgo'),
  ('sesgo.anclaje.example.2.text', 'es-MX', 'En un restaurante, el vino más caro del menú existe para hacer que el segundo más caro parezca razonable — el precio alto ancla la percepción de valor.', 'sesgo'),
  ('sesgo.anclaje.antidote.0', 'es-MX', 'Define tu estimación ANTES de ver cualquier precio o número de referencia.', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.anclaje.antidote.1', 'es-MX', 'Pregúntate: "¿Sería mi estimación la misma si nunca hubiera visto ese número?"', 'sesgo'),
  ('sesgo.anclaje.antidote.2', 'es-MX', 'Usa múltiples metodologías de valuación independientes antes de comparar.', 'sesgo'),
  ('sesgo.anclaje.antidote.3', 'es-MX', 'En negociaciones: si el otro ancla primero, señala explícitamente que el ancla es arbitraria antes de contra-proponer.', 'sesgo'),
  ('sesgo.anclaje.question.0.situation', 'es-MX', 'Una acción que compraste a $150 ahora cotiza a $60. El analista dice que el precio justo es $55. ¿Cómo percibes $60?', 'sesgo'),
  ('sesgo.anclaje.question.0.option.0.text', 'es-MX', 'Está barata — está muy por debajo de los $150 que pagué', 'sesgo'),
  ('sesgo.anclaje.question.0.option.0.reveal', 'es-MX', 'Anclaje: tu precio de compra ($150) contamina tu percepción del valor actual. $60 puede ser caro si el valor es $55', 'sesgo'),
  ('sesgo.anclaje.question.0.option.1.text', 'es-MX', 'Evalúo si $60 es barata o cara basándome en el análisis actual, no en lo que pagué', 'sesgo'),
  ('sesgo.anclaje.question.0.option.1.reveal', 'es-MX', 'Racional: el precio de compra es históricamente irrelevante para la decisión de hoy', 'sesgo'),
  ('sesgo.anclaje.question.1.situation', 'es-MX', 'Vas a negociar tu sueldo. ¿Cuál es tu estrategia?', 'sesgo'),
  ('sesgo.anclaje.question.1.option.0.text', 'es-MX', 'Espero a que el empleador proponga primero — no quiero quedar mal pidiendo mucho', 'sesgo'),
  ('sesgo.anclaje.question.1.option.0.reveal', 'es-MX', 'Error: quien ancla primero tiene ventaja. El primero que menciona un número establece el punto de referencia para toda la negociación', 'sesgo'),
  ('sesgo.anclaje.question.1.option.1.text', 'es-MX', 'Propongo primero un número alto pero razonable — quiero anclar yo la conversación', 'sesgo'),
  ('sesgo.anclaje.question.1.option.1.reveal', 'es-MX', 'Racional: anclar primero con un número ambicioso pero creíble sesga el acuerdo final hacia tu favor', 'sesgo'),
  ('sesgo.anclaje.question.2.situation', 'es-MX', 'Ves un reloj de $5,000 en el aparador de una tienda de lujo. Entras a preguntar por un reloj que buscabas. Te ofrecen uno a $1,200. ¿Cómo lo percibes?', 'sesgo'),
  ('sesgo.anclaje.question.2.option.0.text', 'es-MX', 'Parece razonable — es mucho menos que el de $5,000 de la vitrina', 'sesgo'),
  ('sesgo.anclaje.question.2.option.0.reveal', 'es-MX', 'Anclaje por diseño: las tiendas de lujo ponen artículos caros en la vitrina precisamente para anclar tu percepción de valor', 'sesgo'),
  ('sesgo.anclaje.question.2.option.1.text', 'es-MX', 'Evalúo $1,200 como si no hubiera visto el reloj de $5,000 — ¿es ese precio justo para lo que quiero?', 'sesgo'),
  ('sesgo.anclaje.question.2.option.1.reveal', 'es-MX', 'Racional: el ancla fue colocada intencionalmente para contaminar tu evaluación', 'sesgo'),
  ('sesgo.anclaje.fixation.0.question', 'es-MX', '¿Qué es el "ancla" en el sesgo de anclaje?', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.0', 'es-MX', 'El primer dato que recibimos y que influye desproporcionadamente en nuestra estimación', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.1', 'es-MX', 'El precio final que pagamos por un producto', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.2', 'es-MX', 'La decisión más racional en una negociación', 'sesgo'),
  ('sesgo.anclaje.fixation.1.question', 'es-MX', 'Un vendedor anuncia precio original $10,000 con 50% de descuento. ¿Cuál es el efecto del anclaje?', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.0', 'es-MX', 'El descuento nos hace creer que $5,000 es una ganga, aunque no sepamos si ese era el precio justo', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.1', 'es-MX', 'El precio de $5,000 es objetivamente barato porque bajó', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.2', 'es-MX', 'Solo hay anclaje si el comprador conocía el precio original antes', 'sesgo'),
  ('sesgo.anclaje.fixation.2.question', 'es-MX', 'Según Dan Ariely, ¿qué es la "coherencia arbitraria"?', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.0', 'es-MX', 'Los precios iniciales aleatorios se vuelven el estándar mental con el que comparamos todo lo demás', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.1', 'es-MX', 'Las personas siempre negocian de forma coherente aunque los precios sean arbitrarios', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.2', 'es-MX', 'El cerebro ignora los precios iniciales y decide solo con información nueva', 'sesgo'),
  ('profile.PP.name', 'es-MX', 'Passive Preserver', 'profile'),
  ('profile.PP.nameEs', 'es-MX', 'Preservador Pasivo', 'profile'),
  ('profile.PP.tagline', 'es-MX', 'Emocional · Pasivo — Tu prioridad es proteger lo que tienes', 'profile'),
  ('profile.PP.description', 'es-MX', 'Tiendes a priorizar la seguridad y la preservación de tu patrimonio por encima del crecimiento. Tus decisiones financieras están fuertemente influenciadas por el miedo a perder. Eres cuidadoso y constante, pero corres el riesgo de que la inflación erosione tu capital al evitar el riesgo necesario.', 'profile'),
  ('profile.PP.bias.0.name', 'es-MX', 'Aversión a la pérdida', 'profile'),
  ('profile.PP.bias.0.desc', 'es-MX', 'Sientes las pérdidas con más intensidad que las ganancias equivalentes. Perder $1,000 te duele más de lo que te alegra ganar $1,000.', 'profile'),
  ('profile.PP.bias.1.name', 'es-MX', 'Sesgo de status quo', 'profile'),
  ('profile.PP.bias.1.desc', 'es-MX', 'Prefieres mantener las cosas como están, incluso cuando cambiar podría beneficiarte. "Mejor malo conocido que bueno por conocer."', 'profile'),
  ('profile.PP.bias.2.name', 'es-MX', 'Efecto dotación', 'profile'),
  ('profile.PP.bias.2.desc', 'es-MX', 'Sobrevaloras lo que ya posees simplemente porque es tuyo, lo que te hace resistente a vender o intercambiar.', 'profile'),
  ('profile.PP.recommendation.0', 'es-MX', 'Entiende que la inflación es un riesgo silencioso: no invertir también es arriesgar.', 'profile'),
  ('profile.PP.recommendation.1', 'es-MX', 'Empieza con instrumentos de bajo riesgo pero con rendimiento real (Cetesdirecto, SOFIPOS).', 'profile'),
  ('profile.PP.recommendation.2', 'es-MX', 'Establece reglas claras antes de invertir para que las emociones no dominen.', 'profile'),
  ('profile.PP.recommendation.3', 'es-MX', 'Diversifica gradualmente — no necesitas hacer cambios drásticos, pero sí moverte.', 'profile'),
  ('profile.FK.name', 'es-MX', 'Friendly Follower', 'profile'),
  ('profile.FK.nameEs', 'es-MX', 'Seguidor Amistoso', 'profile'),
  ('profile.FK.tagline', 'es-MX', 'Cognitivo · Pasivo — Buscas orientación en personas de confianza', 'profile'),
  ('profile.FK.description', 'es-MX', 'Tiendes a buscar la opinión de otros antes de tomar decisiones financieras. No es que no pienses — valoras la validación social y el consejo de figuras de autoridad. Tu riesgo está en confiar en voces que suenan seguras pero no necesariamente tienen razón.', 'profile'),
  ('profile.FK.bias.0.name', 'es-MX', 'Efecto manada (Herding)', 'profile'),
  ('profile.FK.bias.0.desc', 'es-MX', 'Tiendes a seguir lo que hace la mayoría. Si todos compran, compras. La multitud no siempre tiene razón.', 'profile'),
  ('profile.FK.bias.1.name', 'es-MX', 'Sesgo de autoridad', 'profile'),
  ('profile.FK.bias.1.desc', 'es-MX', 'Das demasiado peso a la opinión de figuras que percibes como expertos, sin cuestionar si realmente lo son.', 'profile'),
  ('profile.FK.bias.2.name', 'es-MX', 'Sesgo de disponibilidad', 'profile'),
  ('profile.FK.bias.2.desc', 'es-MX', 'Das más importancia a la información más reciente y visible. Si el mercado subió esta semana, crees que seguirá subiendo.', 'profile'),
  ('profile.FK.recommendation.0', 'es-MX', 'Desarrolla tu propio criterio: antes de preguntar, escribe qué harías tú y por qué.', 'profile'),
  ('profile.FK.recommendation.1', 'es-MX', 'Cuestiona las fuentes: ¿esa persona realmente sabe, o solo suena segura?', 'profile'),
  ('profile.FK.recommendation.2', 'es-MX', 'Diversifica tus fuentes de información — no dependas de una sola persona.', 'profile'),
  ('profile.FK.recommendation.3', 'es-MX', 'Practica tomando decisiones pequeñas por tu cuenta para construir confianza.', 'profile'),
  ('profile.II.name', 'es-MX', 'Independent Individualist', 'profile'),
  ('profile.II.nameEs', 'es-MX', 'Individualista Independiente', 'profile'),
  ('profile.II.tagline', 'es-MX', 'Cognitivo · Activo — Analizas, investigas y decides por tu cuenta', 'profile'),
  ('profile.II.description', 'es-MX', 'Eres analítico y autosuficiente. Investigas antes de decidir y confías en tu propio juicio. Tu riesgo está en creer que siempre tienes la razón y que tu análisis es mejor de lo que es en realidad.', 'profile'),
  ('profile.II.bias.0.name', 'es-MX', 'Exceso de confianza', 'profile'),
  ('profile.II.bias.0.desc', 'es-MX', 'Sobreestimas tu capacidad para predecir resultados. Tu análisis puede ser sólido pero no infalible.', 'profile'),
  ('profile.II.bias.1.name', 'es-MX', 'Sesgo de confirmación', 'profile'),
  ('profile.II.bias.1.desc', 'es-MX', 'Buscas información que confirme lo que ya crees e ignoras la que lo contradice. Tu "investigación" puede ser selectiva.', 'profile'),
  ('profile.II.bias.2.name', 'es-MX', 'Ilusión de control', 'profile'),
  ('profile.II.bias.2.desc', 'es-MX', 'Crees que puedes controlar o influir en resultados que en realidad son inciertos o aleatorios.', 'profile'),
  ('profile.II.recommendation.0', 'es-MX', 'Busca activamente opiniones contrarias a las tuyas — si solo lees lo que confirma tu tesis, no estás investigando.', 'profile'),
  ('profile.II.recommendation.1', 'es-MX', 'Acepta que el mercado puede ser irracional más tiempo del que tú puedes ser solvente.', 'profile'),
  ('profile.II.recommendation.2', 'es-MX', 'Lleva un registro de tus predicciones para medir tu precisión real, no la percibida.', 'profile'),
  ('profile.II.recommendation.3', 'es-MX', 'Considera que pedir consejo no es debilidad — incluso los mejores analistas tienen puntos ciegos.', 'profile'),
  ('profile.AA.name', 'es-MX', 'Active Accumulator', 'profile'),
  ('profile.AA.nameEs', 'es-MX', 'Acumulador Activo', 'profile'),
  ('profile.AA.tagline', 'es-MX', 'Emocional · Activo — Actúas rápido y buscas crecimiento', 'profile'),
  ('profile.AA.description', 'es-MX', 'Eres decidido, arriesgado y orientado a la acción. Te gusta tomar el control y no te da miedo apostar. Tu riesgo es confundir actividad con progreso — más operaciones no siempre significan mejores resultados.', 'profile'),
  ('profile.AA.bias.0.name', 'es-MX', 'Exceso de confianza', 'profile'),
  ('profile.AA.bias.0.desc', 'es-MX', 'Tu seguridad al actuar puede hacerte subestimar los riesgos reales.', 'profile'),
  ('profile.AA.bias.1.name', 'es-MX', 'Ilusión de control', 'profile'),
  ('profile.AA.bias.1.desc', 'es-MX', 'Crees que al estar activo y tomar decisiones, controlas el resultado. El azar juega un papel mayor de lo que percibes.', 'profile'),
  ('profile.AA.bias.2.name', 'es-MX', 'Sesgo de acción', 'profile'),
  ('profile.AA.bias.2.desc', 'es-MX', 'Prefieres hacer algo — lo que sea — antes que no hacer nada. A veces la mejor decisión es esperar.', 'profile'),
  ('profile.AA.recommendation.0', 'es-MX', 'Implementa reglas de stop-loss y toma de ganancias ANTES de invertir, no en el momento.', 'profile'),
  ('profile.AA.recommendation.1', 'es-MX', 'No confundas actividad con productividad — a veces la mejor inversión es no hacer nada.', 'profile'),
  ('profile.AA.recommendation.2', 'es-MX', 'Antes de actuar por impulso, espera 24 horas. Si mañana sigue pareciendo buena idea, adelante.', 'profile'),
  ('profile.AA.recommendation.3', 'es-MX', 'Calcula cuánto te han costado tus decisiones impulsivas — el dato te puede sorprender.', 'profile')
